INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-01-006', 'chap-mm-01-01', '6. MENOPAUSE AND MANAGEMENT', 'Detailed medical reference and study guide on 6. MENOPAUSE AND MANAGEMENT.', 6, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-290085e7', 't-mm-01-006', 'html', '<ul><li><em><strong>Average age 50.5years 1 year earlier in smokers</strong></em></li><li><em><strong>Perimenopause:</strong></em></li><li>Interval leading to menopause, anovulatory cycle</li><li><em><strong>Climacteric:</strong></em> period between Reproductive to non-reproductive life.</li></ul>
<p>It includes Menopause.</p>
<ul><li><em><strong>POF:</strong></em>  &lt; 40years</li><li>turner syndrome, Fragile X, Autoimmune Disorders, idiopathic.</li><li>1% of women experience POF</li><li><em><strong>Early menopause</strong></em> &lt; 45 years between age of 40 – 45 yrs.</li><li>E and P =&gt;    FSH Pulsatility</li><li>E and P =&gt; Menopausal symptoms more in 1st year.</li><li>After 1-year estrogen production starts from non-ovarian source leading to reduced symptoms.</li></ul>
<h3><strong>    </strong><strong>Menopause: </strong></h3>
<ul><li>When women have no periods for one ear or more between 45 – 55 years.</li></ul>
<h3><strong>Diagnosis:</strong></h3>
<ul><li><em><strong>&gt; 45 (No labs)</strong></em>        <em><strong>&gt;</strong></em><em><strong> 40 – </strong></em><em><strong>45</strong></em><em><strong> </strong></em></li></ul>
<p>Clinical diagnosis based on:   &gt; 45yrs</p>
<ul><li>Amenorrhea 1 year   FSH &gt; 30IU</li><li>Vasomotor Two levels 4-6</li><li>symptomsweeks apart.</li></ul>
<h3><strong>Clinical Evaluation</strong><strong>:</strong></h3>
<ul><li><em><strong>Vasomotor</strong></em><em><strong> Symptoms</strong></em><em><strong>:</strong></em></li><li>70% more in 1st year due to pulsatile FSH</li><li><em><strong>Urogenital</strong></em><em><strong> Symptoms</strong></em><em><strong>:</strong></em></li><li><em><strong>Genital:</strong></em></li><li>Itching</li><li>Prolapse</li><li>Dyspareunia 40%</li><li>Atrophy</li><li>Dryness 75%</li><li><em><strong>Urologic</strong></em><em><strong>al 50%</strong></em></li><li>Nocturia</li><li>Dysuria</li><li>UTI – Recurrent 20%</li><li>Incontinence.</li><li><em><strong>Psychological:</strong></em></li><li>Fatigue</li><li>Depression</li><li>Mood instability</li><li>libido due to    Testosterone and atrophy</li><li>Memory loss</li><li>insomnia</li><li><em><strong>Osteoporosis:</strong></em></li><li>More in vertebrae, femur, wrist.</li><li>2% @ 50yrs</li><li>25% @ 80yrs</li></ul>
<h3><strong>Diagnosis:</strong></h3>
<ul><li><em><strong>Dexa scan</strong></em></li><li>T-score comparison with 30yr healthy women</li><li>Z-score among same age group</li><li><em><strong>T-score</strong></em><strong> </strong></li><li>Normal: -1 to + 1</li><li>Osteopenia: -1 to -2.5</li><li>Osteoporosis: &lt; -2.5</li></ul>
<h3><strong>MANAGEMENT OF MENOPAUSE:</strong></h3>
<ul><li><em><strong>Vasomotor</strong></em><em><strong> symptoms</strong></em><em><strong>:</strong></em></li></ul>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-fd6bf8cb', 't-mm-01-006', 'html', '<table><tbody><tr><td><strong>Estrogen replacement therapy ERT</strong></td><td><strong>Hormone replacement therapy HRT </strong><strong> combined </strong><strong>estrogen + progesterone</strong></td></tr><tr><td>No uterus</td><td>With uterus</td></tr></tbody></table>', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4116bb98', 't-mm-01-006', 'html', '<ul><li>HRT: offer as 1st line until contraindications</li><li>SSRI, SNRI, clonidine</li><li>Don''t offer as 1st line</li><li>Black cohosh + Isoflavones</li><li>No safety data but can improve symptoms.</li><li><em><strong>Psychological:</strong></em></li><li>HRT (consider)</li><li>To improve mood</li><li>CBT (consider)</li><li>No role of SSRI, SNRI to ease low mood.</li><li><em><strong>Urogenital atrophy:</strong></em></li><li>Vaginal estrogen (offer)</li><li>even patients are on HRT to improve local symptoms.</li><li>Consider even if systemic HRT is Contraindicated.</li><li>No relief    Dose after advice from expert</li><li>No endometrial thickness monitoring is required with vaginal estrogen.</li><li>Lubricants:</li><li>For local dryness along with estrogen.</li><li>If vaginal estrogen and lubricants are not effective/ not tolerated offer vaginal progesterone.</li><li>If vaginal treatment impractical.</li><li>e.g,. disability</li><li>Consider ospemifene oral treatment</li><li><em><strong>Altered Sexual Function:</strong></em></li><li>Testosterone.</li><li>consider if HRT alone is not effective.</li><li><em><strong>Osteoporosis:</strong></em></li><li>Prophylaxis</li><li>HRT</li><li>Raloxifene SERM</li><li>Tibolone with GnRH analogue  if given for &gt; 6months.</li><li>Therapeutic</li><li>Bisphosphate + Calcium 1.5g + vitamin D 400 - 600 daily.</li></ul>
<p><strong>1st line:</strong> Alendronate if T score is &lt; 2.5.it inhibits osteoporosis</p>
<p><strong>2nd line:</strong> Risedronate &amp; Etidronate if  T score is - 2.5 - 3 or Alendronate is Contraindications.</p>
<p><strong>3rd line:</strong> Strontium Ranelate (2g/day Hs) &amp; Raloxifene if T - score is - 2.5 - 4 or Age &gt; 54.</p>
<p><strong>4th line:</strong> teriparatide</p>
<p>&gt;40-50% discontinue t/m after 1yr.</p>
<p>&gt;65-75% after 2yrs.</p>
<h3><strong>Vaginal Estrogen Deficiency:</strong></h3>
<ul><li>Moisturizer &amp; lubricates - effective in mild-moderate dryness - short term relief of dyspareunia.</li><li>Vaginal E deficiency - short term relief</li><li>HRT</li><li>Laser treatment – can be given to women where estrogen is contraindication.</li></ul>
<h3><strong>SERM:</strong></h3>
<h3><strong>1. </strong><strong>Ospem</strong><strong>ife</strong><strong>ne</strong></h3>
<ul><li><strong>Lasofoxifene</strong><strong> </strong></li><li>Oral: given where estrogen is contraindicated, licensed for dyspareunia.</li><li><strong>Tissue selective E complex</strong> treatment - oral.</li><li><strong>Androgens </strong>DHEA - oral/vaginal can b given in vulvovaginal atrophy</li></ul>', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
