INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-377a4be1', 't-mm-01-017', 'html', '<h3><strong>CUA </strong><strong>incidences</strong><strong>:</strong></h3>
<ul><li><em><strong>2-4 % </strong></em><em><strong>overall </strong></em><em><strong>incidence</strong></em></li><li>Septate 90%</li><li>Bicornuate 5%</li><li>Didelphys 5%</li><li>5.5% - unselected population</li><li>8% - sub fertile women</li><li>13.3% in miscarriages</li><li>24.5% miscarriage + sub fertility.</li><li><em><strong>Classification ASRM</strong></em></li><li><strong>Hypoplasia/Aplasia</strong></li><li>Vaginal</li><li>Cervical</li><li>Fundal</li><li>Tubal</li><li>Combined MRKH</li></ul>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
