INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-02-001', 'chap-mm-02-01', '1. FERTILITY PROBLEMS, ASSESSMENT & TREATMENT', 'Detailed medical reference and study guide on 1. FERTILITY PROBLEMS, ASSESSMENT & TREATMENT.', 1, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-41f2c948', 't-mm-02-001', 'html', '<ul><li>Assessment after 1 year of trying.</li><li>Couple should be seen together.</li><li>Verbal, written &amp; visual information.</li><li>Specialist care improves chances of conception &amp; satisfaction.</li><li>Counselling:</li><li>By person not involved in treatment.</li><li>Before, during and after work up.</li><li>1. unprotected sex.2. Age &lt;40 3. Regular sex1. unprotected sex.2. Age &lt;40 3. Regular sex1. unprotected sex.2. Age &lt;40 3. Regular sex1. unprotected sex.2. Age &lt;40 3. Regular sexChances of conception.</li><li>1 year – 80% conceive</li><li>2 years – 90% conceive</li></ul>
<h3><strong>Success rate:</strong></h3>
<ul><li><strong>IUI:</strong></li><li>Initial 6 cycles – 50% (if age &lt;40).</li><li>Another 6 cycles – 75% (if age &lt;40).</li><li>More chances with Fresh sperms than thawed/frozen.</li><li>I/U insemination rather Intracervical.</li></ul>
<h3><strong>Factors affecting Fertility:</strong></h3>
<ul><li><em><strong>Age:</strong></em></li><li>Single best predictor in Female partner.</li><li>Lesser extent male partner.</li><li><em><strong>Stress:</strong></em><em><strong> decreases</strong></em></li><li>Libido.</li><li>Sex frequency.</li><li>Conception.</li><li><em><strong>Intercour</strong></em><em><strong>s</strong></em><em><strong>e</strong></em><em><strong>:</strong></em><em><strong> recommended</strong></em></li><li>Every 2 – 3 days.</li><li><em><strong>Alcohol:</strong></em></li><li>Women: 1 – 2 units/week.</li><li>Men: 3 – 4 units/day.</li><li>Alcohol - Deteriorates   Quality of semen.</li><li><em><strong>Smoking:</strong></em></li><li>Female fertility – passive smoking also affects.</li><li>affect Quality of Semen – stopping smoking improve semen quality and general health.</li><li><em><strong>Caffeinated drinks:</strong></em></li><li>No consistent association.</li><li><em><strong>Over the Counter Drugs</strong></em><em><strong> and recreational drugs:</strong></em></li><li>Inquire about drugs as they may interfere with male &amp; female infertility.</li></ul>
<h3><strong>BMI:</strong></h3>
<ul><li>Low &lt;19 –     Fertility.</li><li>High &gt;30 –    female and</li><li>male fertility.</li></ul>
<h3><strong>Advice:</strong></h3>
<ul><li>Regarding diet + Exercise rather weight reduction alone.</li></ul>
<h3><strong>Tight underwear’s:</strong></h3>
<ul><li>reduce Semen Quality.</li></ul>
<h3><strong>Occupation:</strong></h3>
<ul><li>Chemical hazards</li><li>Heat also affects semen parameters</li><li>Folic acid.</li><li>400mg – routinely.</li><li>5mg.</li><li>NTD – History.</li><li>Epilepsy drugs.</li><li>DM.</li><li>BMI &gt;30</li></ul>
<h3><strong>Complementary Therapy: </strong></h3>
<ul><li>Not evaluated.</li></ul>
<h3><strong>Assessment of Fertility:</strong></h3>
<ul><li><em><strong>When</strong></em></li><li>1 year without known factors.</li><li>6 cycles of IUi.</li><li>Earlier if:</li><li>Age &gt;35</li><li>Cause of infertility present.</li><li>Predisposing factors.</li><li>Treatment is planed that can cause infertility.</li></ul>
<h3><strong>Investigations:</strong></h3>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
