INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a9a9d7fc', 't-mm-02-002', 'html', '<ul><li><strong>Semen Analysis</strong><strong>:</strong></li><li><em><strong>WHO criteria:</strong></em></li><li>PH = 7.2 or more.</li><li>Volume = 1.5ml or more.</li><li>Sperm count = 39million/ ejaculate or more.</li><li>Sperm concentration = 15million/ml or more.</li><li>Motility:</li><li>Total 40%.</li><li>Progressive 32%.</li><li>Vitality = 58% or more.</li><li>Morphology = 4% normal or more.</li></ul>
<h3><strong>Repeat Testing:</strong></h3>
<p>3months routinely if abnormality detected</p>
<p>Except Azoospermia or severe oligospermia.</p>
<p>Repeat as early as possible.</p>
<ul><li><strong>Anti-Sperm Anti bodies: N</strong><strong>ot recommended</strong></li><li><strong>PCT = N</strong><strong>ot recommended</strong></li></ul>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
