INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-02-014', 'chap-mm-02-01', '8. EARLY OVARIAN AGING', 'Detailed medical reference and study guide on 8. EARLY OVARIAN AGING.', 14, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-08f2d157', 't-mm-02-014', 'html', '<h3><strong>Definition:</strong></h3>
<ul><li>Low ovarian reserve @ young age and accelerated loss of ovarian follicle in early thirties/ before 40 yr of age</li><li>EOA includes all women who attain Menopause before 45 years</li><li>EOA is precursor to early Menopause or POI</li></ul>
<p>Incidence: 10% overall</p>
<h3><strong>Etiology: RF</strong></h3>
<ul><li>Genetic factors</li><li>Smoking</li><li>Infections</li><li>Autoimmune</li><li>Fetal environment, in utero factors</li><li>Chemo/Radio</li><li>Endometriosis.</li></ul>
<h3><strong>Consequences:</strong></h3>
<ul><li>Subfertility – early loss of fertility due to depletion of ovarian reserves</li><li>Aneuploidy</li><li>Miscarriage</li><li>POI =&gt; long term consequences</li><li>Osteoporosis</li><li>Cardio vascular effects</li><li>Urogenital problems</li><li>Gonadal age</li></ul>
<p>more in women with EOA</p>
<h3><strong>How to </strong><strong>counse</strong><strong>l regarding fertility:</strong></h3>
<ul><li>Don’t delay</li><li>Conservative/natural conception 18%</li><li>IUI 15%</li></ul>
<h3><strong>Fertility preservation:</strong></h3>
<ul><li>Embryo preservation – couple</li><li>Oocyte preservation – single women</li><li>Or embryo preservation with donor egg</li><li>IVF.</li></ul>
<h3><strong>Prevention:</strong></h3>
<ul><li>Fertility Education to couples and women.</li><li>Educate girls regarding fertility in schools</li><li>Stem cell therapy – being tried</li><li>Mitochondrial transfer being tried</li><li>Antioxidants to reduce apoptosis like CO – Q10.</li></ul>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
