INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d1edef20', 't-mm-03-007', 'html', '<p><strong>2.</strong> Omentectomy</p>
<p><strong>3.</strong> peritoneal</p>
<p>washings</p>
