INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2ba614ee', 't-mm-04-005', 'html', '<table><tbody><tr><td><strong>Types of Q Max</strong></td><td><strong>Causes</strong></td></tr><tr><td>Several Peaks</td><td>1. out flow obstruction.<br/>2. unstained detrusor contractions.</td></tr><tr><td>2. Reduced Q Max plateau</td><td>1. urethral stricture.<br/>2. External urethral compression.<br/>3. Prolapse – (Bladder outflow obstruction).<br/>4. A contractile detrusor.</td></tr><tr><td>3. Very High Q Max</td><td>1. Detrusor over Activity.</td></tr></tbody></table>', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
