INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6142906c', 't-mm-04-015', 'html', '<h3><strong>History:</strong></h3>
<ul><li>Related to prolapse</li><li>Bowel complaints</li><li>Urinary complaints</li><li>Sexual problems</li></ul>
<h3><strong>Examination:</strong></h3>
<ul><li>POP Q.</li><li>Pelvic floor Activity.</li><li>Vaginal atrophy.</li><li>Rule out pelvic mass or Pathology.</li></ul>
<p>Examination inconclusive but symptoms are there.</p>
<p>Do @ other time or other position.</p>
<h3><strong>Investigations:</strong></h3>
<h3>Not required routinely, Do if:</h3>
<ul><li>Bowel symptoms.</li><li>Urinary symptoms</li><li>Un explained symptoms.</li><li>Pain.</li></ul>
<h3><strong>POP Q:</strong></h3>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-634793a2', 't-mm-04-015', 'html', '<table><tbody><tr><td><strong>Aa</strong><br/>Descent of fixed point on anterior wall</td><td><strong>B</strong><strong>a</strong><br/>The Lowest part of upper anterior vaginal wall</td><td><strong>Cc</strong><br/>The Lowest part of cervix</td></tr><tr><td><strong>GH</strong><br/>Genital Hiatus</td><td><strong>PB </strong><br/>perineal Body</td><td><strong>TVC </strong><br/>Total Vaginal Length</td></tr><tr><td><strong>AP</strong><br/>Descend of fixed point on posterior wall</td><td><strong>BP</strong><br/>The Lowest part of the upper posterior vaginal wall.</td><td><strong>D</strong><br/>Vault or insertion of uterosacral</td></tr></tbody></table>', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6f3b7d9d', 't-mm-04-015', 'html', '<h3><strong>Stages of Prolapse:</strong></h3>', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ea1c01dc', 't-mm-04-015', 'html', '<table><tbody><tr><td><strong>Stage 0</strong></td><td>No prolapse<br/>Aa, Ba, BP, AP = - 3cm.<br/>C or D &lt; TVL – 2cm.</td></tr><tr><td><strong>Stage 1</strong></td><td>Leading edge - 1cm.</td></tr><tr><td><strong>Stage 2</strong></td><td>Leading edge &gt; - 1cm but &lt; + 1cm.</td></tr><tr><td><strong>Stage 3</strong></td><td>Leading edge &gt; + 1cm but &lt; + (TVL – 2cm).</td></tr><tr><td><strong>Stage 4</strong></td><td>Leading edge &gt; + (TVL – 2).</td></tr></tbody></table>', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a8f2a648', 't-mm-04-015', 'html', '<h3><strong>Management:</strong></h3>
<ul><li><em><strong>Life style:</strong></em></li><li>Weight loss.</li><li>Minimum weight lifting.</li><li>Control constipation.</li><li><em><strong>Topical E</strong></em><em><strong>:</strong></em></li><li>Atrophic vagina.</li><li>Old, frail, mentally handicap</li><li>E secreting pessary where pessary or cream application is difficult =&gt; (Estring)</li><li><em><strong>Pelvic floor exercises: PFME</strong></em></li></ul>
<p>-Stage 1 &amp; 2</p>
<p>-F/U @ 16 weeks.</p>
<p>-Continue if effective.</p>
<ul><li><em><strong>Vaginal pessaries</strong></em></li><li>Symptomatic prolapse.</li><li>Unfit for surgery.</li><li>Offred alone or with PFME</li></ul>
<h3><strong>Types:</strong></h3>
<ul><li><strong>Ring</strong> common, with or without E, failure with deficient perineum.</li><li><strong>Shelf</strong> – more support, sexually in active, unfit for surgery, @ level of ischial spies.</li><li><strong>G – cup</strong> – mild symptoms.</li><li><strong>GELL horn</strong>.</li><li><strong>Donut</strong> – less traumatic.</li><li><strong>Horse shoe shape pessary or Arabian Pessary</strong> – used in pregnancy to reduce the risk of pre – term birth. It helps in management of UVP and cervical insufficiency in pregnancy.</li></ul>
<h3><strong>S/E:</strong></h3>
<ul><li>Loss of sexual function.</li><li>Recurrent infections.</li><li>Unfit pessary:</li><li>Under sized – loose, fell off</li><li>Oversized – urinary retention, UTI, ulcers.</li></ul>
<h3><strong>Replacement:</strong></h3>
<ul><li>Every 6m0.</li></ul>
<h3><strong>Surgical Treatment:</strong></h3>
<ul><li>Symptoms not controlled.</li><li>Reluctant for non-surgical treatment.</li><li>Anterior + Apical prolapse</li></ul>
<h3><strong>Fertility sparing Procedures:</strong></h3>
<ul><li>Sacro hysteropexy.</li><li>Vaginal sacrospinous hysteropexy.</li><li>Manchester Repair</li></ul>
<h3><strong>Not wishing to retain uterus:</strong></h3>
<ul><li>Vaginal hysterectomy + SSF.</li></ul>', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-04-016', 'chap-mm-04-01', '10.VAULT PROLAPSE', 'Detailed medical reference and study guide on 10.VAULT PROLAPSE.', 16, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
