INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-88c0e9cf', 't-mm-05-001', 'html', '<h3><strong>Vaginal discharge</strong></h3>
<ul><li>Bacterial vaginosis BV</li><li>Vulvovaginal candidiasis VVC</li><li>Trichomonas vaginalis TV</li></ul>
<h3><strong>Cervical dx:</strong></h3>
<ul><li>Chlamydia trachomatis CT</li><li>Neisseria gonorrhea NG</li></ul>
<h3><strong>History</strong>:</h3>
