INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-88b1658a', 't-mm-05-005', 'html', '<ul><li><strong>90% warts are due to HPV,.890% warts are due to HPV,.8</strong>90% warts are due to HPV,.890% warts are due to HPV,.8<strong>Vaginal Vulval / Perianal wartsVaginal Vulval / Perianal warts</strong><strong>Vaginal Vulval </strong><strong>/</strong><strong> Perianal warts</strong><strong>Vaginal Vulval </strong><strong>/</strong><strong> Perianal warts</strong></li></ul>
