INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c0327194', 't-mm-05-007', 'html', '<table><tbody><tr><td><strong>HIV INFECTION </strong></td><td>&nbsp;</td></tr><tr><td>HIV infection</td><td>&nbsp;</td></tr><tr><td>a) High risk of HIV infection</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>b) HIV infected</td><td>&nbsp;</td></tr><tr><td>(i) CD4 count ≥200 cells/mm³</td><td>2</td><td>2</td><td>1</td><td>1<br/>1</td><td>1</td></tr><tr><td>(ii) CD4 count &lt;200 cells/mm²</td><td>I</td><td>C</td><td>I</td><td>C</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>&nbsp;</td><td>3</td><td>2</td><td>3</td><td>2</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>c) Taking antiretroviral (ARV) drugs</td><td>Certain ARV drugs have the potential to affect the bioavailability of steroid hormones in hormonal contraception.<br/>For up-to-date information on the potential drug interactions between hormonal contraception and ARV drugs, please refer to the online HIV drugs interaction checker<br/>(www.hiv-druginteractions.org/Interactions.aspx).</td></tr><tr><td><strong>OTHER INFECTIONS</strong></td><td>&nbsp;</td></tr><tr><td><strong>Tuberculosis</strong></td><td>&nbsp;</td></tr></tbody></table>', 14) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
