INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-304c39c0', 't-mm-05-022', 'html', '<table><tbody><tr><td>Method</td><td>Perfect Use (%)<strong> </strong><strong>(Theoretical Effectiveness)</strong></td><td>Typical Use (%)<strong> </strong><strong>(Real-World Effectiveness)</strong></td></tr><tr><td>Vasectomy</td><td>0.10</td><td>0.10</td></tr><tr><td>Tubal sterilization</td><td>0.50</td><td>0.50</td></tr><tr><td>Progestogen subdermal implant</td><td>0.05</td><td>0.05</td></tr><tr><td>LNG-IUS (Levonorgestrel intrauterine system)</td><td>0.20</td><td>0.20</td></tr><tr><td>Cu-IUD (Copper intrauterine device)</td><td>0.60</td><td>0.80</td></tr><tr><td>DMPA injection (Depot-medroxyprogesterone acetate)</td><td>0.20</td><td>6.00</td></tr><tr><td>Progestogen-only pill</td><td>0.30</td><td>9.00</td></tr><tr><td>Combined hormonal contraception (pill/ring/patch)</td><td>0.30</td><td>9.00</td></tr><tr><td>Condom</td><td>2.00</td><td>18.00</td></tr><tr><td>Diaphragm</td><td>6.00</td><td>12.00</td></tr><tr><td>Fertility awareness</td><td>0.40 – 5.00</td><td>24.00</td></tr><tr><td>No contraception</td><td>85.00</td><td>85.00</td></tr></tbody></table>', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
