INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-eef64b71', 't-mm-06-006', 'html', '<table><tbody><tr><td>&nbsp;</td><td><strong>P</strong><strong>rocedure</strong><strong>/complication</strong></td><td><strong>Vessel involved</strong></td></tr><tr><td><strong>1. </strong></td><td>Laparoscopic P0 port</td><td>Rt common iliac, descending aorta</td></tr><tr><td><strong>2.</strong></td><td>secondary port</td><td>Deep inferior epigastric artery</td></tr><tr><td><strong>3. </strong></td><td>4th degree tear</td><td>Inferior rectal – (internal pudendal)</td></tr><tr><td><strong>4.</strong></td><td>3rd degree</td><td>Inferior rectal – (internal pudendal)</td></tr><tr><td><strong>5.</strong></td><td>Midline episiotomy</td><td>Inferior rectal – (internal pudendal)</td></tr><tr><td><strong>6.</strong></td><td>SSF</td><td>INF gluteal (Ant division of internal iliac)</td></tr><tr><td><strong>7.</strong></td><td>TOT</td><td>Obturator (Ant division internal iliac)</td></tr><tr><td><strong>8.</strong></td><td>Vulval haematoma due to local/ episiotomy</td><td>Internal pudendal</td></tr><tr><td><strong>9.</strong></td><td>Vaginal haematoma</td><td>Vaginal artery</td></tr><tr><td><strong>10.</strong></td><td>Forceps delivery</td><td>Above piriformis – sup gluteal posterior division of internal iliac artery<br/>Below piriformis – inf gluteal Anterior division of internal iliac artery</td></tr><tr><td><strong>11.</strong></td><td>Rectus Sheath Haematoma</td><td>Inf epigastric</td></tr><tr><td><strong>12.</strong></td><td>Medio lateral episiotomy</td><td>perineal artery branch of internal pudendal artery, inferior rectal artery</td></tr><tr><td><strong>13.</strong></td><td>pudendal block</td><td>Internal pudendal</td></tr><tr><td><strong>14.</strong></td><td>Ruptured uterus with retro peritoneal haematoma</td><td>Internal iliac</td></tr><tr><td><strong>15.</strong></td><td>Caphal haematoma</td><td>Sup periosteal blood vessels</td></tr><tr><td><strong>16.</strong></td><td>Burch Colposuspension</td><td>Deep circumflex iliac Branch of external iliac</td></tr><tr><td><strong>17.</strong></td><td>Cone biopsy</td><td>Cervical branch of vaginal A</td></tr><tr><td><strong>18.</strong></td><td>Vault haematoma after TAH</td><td>Ascending cervical branch of vaginal artery/ Azygous Artery</td></tr><tr><td><strong>19.</strong></td><td>Broad ligament haematoma</td><td>Internal iliac artery</td></tr><tr><td><strong>20.</strong></td><td>Largest branch of internal iliac</td><td>Superior gluteal artery</td></tr><tr><td><strong>21.</strong></td><td>Trocar insertion lateral to midline</td><td>Inf vena cava</td></tr><tr><td><strong>22.</strong></td><td>Opening peritoneum in laparoscopy</td><td>Umbilical artery, uracus</td></tr><tr><td><strong>23.</strong></td><td>TVT</td><td>Internal pudendal A</td></tr><tr><td><strong>24.</strong></td><td>Abdominal Sacro colpopexy</td><td>vertebral artery</td></tr><tr><td><strong>25. </strong></td><td>Superior gluteal is branch of</td><td>Posterior division of internal iliac artery</td></tr><tr><td><strong>26.</strong></td><td>Inferior gluteal is branch of</td><td>Anterior division of internal iliac artery</td></tr></tbody></table>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
