INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-06-028', 'chap-mm-06-01', '17.9.4. ACUTE COLONIC PSEUDO – OBSTRUCTION (ACPO) AFTER C/S', 'Detailed medical reference and study guide on 17.9.4. ACUTE COLONIC PSEUDO – OBSTRUCTION (ACPO) AFTER C/S.', 28, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-64229a5f', 't-mm-06-028', 'html', '<h3><strong>Ogilivie Syndrome:</strong></h3>
<ul><li>1/500 delivery 400/year</li><li>Parasympathetic underactivity, sympathectic over activity.</li><li>10% due to C/Section and pelvic surgery.</li></ul>
<p><strong>Sympathetic:</strong> L2 – L5 =&gt; inferior mesentric and pelvic ganglion.</p>
<p><strong>Para:</strong> vagus + Hypogestic plexus S1 – S4</p>
<h3><strong>Risk Factor:</strong></h3>
<ul><li>Age</li><li>Anticholinergic drugs</li><li>Alpa – agonist sympathomimetics</li><li>Cells of cajal in colon</li><li>Hypokelemia, hypomegnesimea</li><li>Gravid uterus – pressure on sacral plexus – risk of ACPO.</li></ul>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-7583891d', 't-mm-06-028', 'image', '/uploads/content-images/maternal_mind_book/image73.png', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
