INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a6ec1d7b', 't-mm-07-001', 'html', '<ul><li><strong>Work up:</strong></li><li>USG of all women with three 1st &amp; one 2nd miscarriage</li></ul>', 12) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
