INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-4f1e1e1f', 't-mm-07-005', 'html', '<h3><strong>Parenteral</strong><strong> Nutrition TPN:</strong></h3>
<ul><li>with MDT discussion</li><li>used as last resort</li><li>Complication of TPN</li><li>Refeeding syndrome.</li></ul>
<h3><strong>MDT: </strong></h3>
<ul><li>midwife nurse dietician, Pharmacist, endocrinologists’ nutritionist, Gastroenterologist, Mental health team.</li></ul>
<h3><strong>TOP 10% of HG:</strong></h3>
<ul><li>when all therapeutic options failed including parenteral nutrition after MDT discussion.</li></ul>
<h3><strong>Reoccurrence: </strong></h3>
<ul><li>15.2 – 8%.</li></ul>
<p>Advice regarding diet &amp; antiemetic’s that worked previously.</p>', 15) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
