INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d578c10d', 't-mm-08-004', 'html', '<h3><strong>Targets:</strong></h3>
<ul><li>Xa = 0.5 – 1IUml.</li><li>A PTT = 1.5 – 2.5.</li><li>INR = 2 – 3.</li></ul>
<h3><strong>PE (massive life threatening PE):</strong></h3>
<ul><li>MDT.</li><li>UfH I/V:</li><li>Loading dose 80 units/kg+ maintenance dose 18iu/kg.</li><li>Target APTT 1.5 – 2.5times.</li><li>APTT – 4 – 6hrs after loading dose, 6 hours after any dose change.</li><li>At least daily when therapeutic range is achieved.</li><li>Monitoring is difficult in late pregnancy due to   Fibrinogen   VIII</li><li>Involve haematologist =&gt; Monitor x – a (0.5 – 1.0)</li></ul>', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
