INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e89d7b1f', 't-mm-08-007', 'html', '<h3><strong>S/E:</strong></h3>
<ul><li>Malaise.</li><li>Hypothermia.</li><li>Abdominal pain.</li><li>Nausea, vomiting</li><li>Arthralgia.</li><li>Rise in Hb – 7 days.</li></ul>
<h3>Indications:</h3>
