INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6678130f', 't-mm-08-008', 'html', '<table><tbody><tr><td>&nbsp;</td><td><strong>HTN</strong><br/>HTN &lt;160/110</td><td><strong>Severe HTN</strong><br/>B.P &gt; 160/110</td><td><strong>Pre eclampsia</strong><br/>B.P &lt; 160/110</td><td><strong>Severe </strong><strong>E</strong><strong>clampsia</strong><br/>B.P &gt; 160/110</td></tr><tr><td>Admission</td><td>* Not required</td><td>Admit till B.P &lt; 160/110</td><td>Admit if clinical concerns.</td><td>Admit till B.P &lt;160/110.</td></tr><tr><td>Anti-hypertensive</td><td>B.P &gt; 140/90</td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td>Target B.P</td><td>135/85 or less</td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td>B.P monitoring</td><td>1 – 2 times/ week<br/>(weekly)</td><td>Every 15 – 30 min till B.P &lt;160/110</td><td>Twice/ thrice weekly (every 48 hours)</td><td>15 – 30 min till B.P &lt;160/110 then 4 hourly.</td></tr><tr><td>Proteinuria</td><td>1 – 2/ week</td><td>Daily while admitted</td><td>Repeat if clinically indicated</td><td>If clinically indicated.</td></tr><tr><td>Blood Testing</td><td>Weekly</td><td>Weekly</td><td>twice/ week</td><td>thrice/ week</td></tr><tr><td>PIGE Testing</td><td>20 – 35 weeks</td><td>20 – 35 weeks</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td><strong>Fetal Assessment:</strong></td></tr><tr><td>FHR Auscultation</td><td>Every visit</td><td>Every visit</td><td>Every visit</td><td>Every visit</td></tr><tr><td>CTG</td><td>If clinically indicated</td><td>@ diagnosis then if clinically indicated</td><td>@ diagnosis then if clinically indicated</td><td>@ diagnosis then if clinically indicated</td></tr><tr><td>USG</td><td>2 – 4 weeks</td><td>2 weeks</td><td>2 weeks</td><td>2 weeks</td></tr><tr><td><strong>Timing of Birth:</strong><strong> </strong>discussed below</td></tr><tr><td><strong>Post Natal</strong><strong> care </strong><strong> </strong></td><td>Ask about Epigastric pain and headache while checking B.P.</td></tr><tr><td>B.P monitoring</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>Daily for</td><td>2 days</td><td>2 days</td><td><strong>On treatment:</strong><br/>4 hourly during admission<br/>Every day or alternate days till 2weeks<br/><strong>Without Treatment:</strong><br/>4 hourly during admission<br/>Once for 3 – 5 days<br/>Alternate days till B.P is normal</td></tr><tr><td>Once for next</td><td>3 – 5 days</td><td>3 – 5 days</td><td>&nbsp;</td></tr><tr><td>Once on day</td><td>15</td><td>15</td><td>&nbsp;</td></tr><tr><td>Once in</td><td>6 – 8 weeks</td><td>6 – 8 weeks</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>Start Anti-Hypertensive if</td><td>B.P &gt; 150/100</td><td>B.P &gt; 150/100</td><td>B.P &gt; 150/100<br/>B.P &lt; 130/80<br/>*  48 – 72 hours after Birth.<br/>Normal =&gt; no need to repeat.<br/>U/A: 6 – 8 weeks =&gt; repeat 3m0 Postnatal.</td></tr><tr><td>Target B. P</td><td>B.P &lt; 130/80</td><td>B.P &lt; 130/80</td><td>&nbsp;</td></tr><tr><td>Hematological Tests</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr></tbody></table>', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3265c086', 't-mm-08-008', 'html', '<p>Table 31. HTN in Pregnancy</p>
<h3><strong>Timing of Delivery:</strong></h3>
<ul><li><strong>CH HTN and Gestational Hypertension, </strong>B.P &lt;160/100, Delivery not before 37 weeks</li><li>Delivery after 37 weeks according to obstetric review and women choices</li><li><strong>Pre – Eclampsia and B.P &gt;160/110: </strong>Formulate birth plan</li></ul>
<h3><strong>* Decision Making Factors</strong><strong> for timing of birth</strong><strong>:</strong></h3>
<ul><li>Uncontrolled B.P despite 3 classes of antihypertensive with appropriate doses.</li><li>O2 sat &lt; 90%</li><li>Progressive deterioration in LFT’S, RFT’S, hemolysis, low Plt.</li><li>Ongoing neurological symptoms.</li><li>Abruption.</li><li>REDF in U/A Doppler.</li><li>Non – reassuring CTG/ Still birth.</li></ul>
<h3><strong>* Team Involved in Decision</strong><strong> Making</strong><strong>:</strong></h3>
<ul><li>Senior Obstetrician.</li><li>Anesthetist.</li><li>Neonatologist.</li></ul>
<h3><em><strong>Offer:</strong></em></h3>
<ul><li>Steroid and mgso4 in pre – Term babies before 37 weeks.</li></ul>
<h3><em><strong>Timing:</strong></em></h3>
<ul><li>Before 37 weeks if any of above worsening factor.</li></ul>
<h3><em><strong>After 37:</strong></em></h3>
<ul><li>Initiate within 24 – 48 hours.</li></ul>
<h3><strong>Fetal Monitoring:</strong></h3>', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9900e316', 't-mm-08-008', 'html', '<table><tbody><tr><td><strong>USG</strong></td><td><strong>CH HTN</strong></td><td><strong>Gest HTN</strong></td><td><strong>Severe HTN + PE</strong></td></tr><tr><td>- Biometry (growth)<br/>+ AFI<br/>+ U/A Doppler</td><td>28weeks<br/>32 weeks<br/>36 weeks</td><td>@ diagnosis then every 2 weeks.</td><td>@ diagnosis then every 2 weeks.</td></tr><tr><td>CTG</td><td>If clinically indicated</td><td><strong>USG, EFW, AFI, U/A Doppler.@ between 28 – 30 weeks or 2 weeks before previous event.Repeat: 4 weekly if (N).USG, EFW, AFI, U/A Doppler.@ between 28 – 30 weeks or 2 weeks before previous event.Repeat: 4 weekly if (N).</strong><strong>USG</strong><strong>,</strong><strong> EFW, AFI, U/A Doppler.</strong>@ between 28 – 30 weeks or 2 weeks before previous event.<strong>Repeat:</strong> 4 weekly if (N).<strong>USG</strong><strong>,</strong><strong> EFW, AFI, U/A Doppler.</strong>@ between 28 – 30 weeks or 2 weeks before previous event.<strong>Repeat:</strong> 4 weekly if (N).If clinically indicated<br/><strong>USG</strong><strong>,</strong><strong> EFW, AFI, U/A Doppler.</strong><br/>@ between 28 – 30 weeks or 2 weeks before previous event.<br/><strong>Repeat:</strong> 4 weekly if (N).<br/><strong>USG</strong><strong>,</strong><strong> EFW, AFI, U/A Doppler.</strong><br/>@ between 28 – 30 weeks or 2 weeks before previous event.<br/><strong>Repeat:</strong> 4 weekly if (N).</td><td>@ diagnosis repeat if clinically indicated or:<br/>-  RFM<br/>- Bleeding.<br/>- Abd pain.<br/>- deterioration of maternal condition.</td></tr></tbody></table>', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-969fc8c0', 't-mm-08-008', 'html', '<h3><strong>Women with</strong><strong> previous</strong><strong> History of:</strong></h3>
<ul><li>Severe pre-eclampsia</li><li>PE resulted in Birth</li><li>Before 34 weeks.</li><li>IUGR &lt; 10th centile.</li><li>IUD.</li><li>Abruption.</li></ul>
<p>Offer usg for EFW,AFI and umbilical artery doppler @between 28-30 weeks or 2 weeks before the previous event. Repeat after 4 weeks if results are normal</p>
<h3><strong>Management in </strong><strong>critical</strong><strong> setting:</strong></h3>
<ul><li>Severe HTN, severe Pre-eclampsia, history of fits, planned birth in 24 hours =&gt; I/V Mgso4</li><li>Give Mgso4 in pre-eclampsia with any of following</li><li>1.Ongoing headache</li><li>2.Visual scotoma.</li><li>3.Nausea vomiting.</li><li>4.Epigastric pain.</li><li>5.Oliguria/ Severe HTN.</li><li>6.Progressive deterioration</li><li>of lab tests.</li></ul>
<p><strong>Eclampsia</strong><strong> </strong><strong>Mgso4</strong><strong> Loading</strong>4g I/V in 5 – 15 min.</p>
<p><strong>Maintenance</strong> 1g/hr./24 hours of last fit.</p>
<p><strong>Repeat fit</strong>2 – 4g repeat Bolus.</p>
<h3><strong>Regional An</strong><strong>a</strong><strong>esthesia:</strong></h3>
<ul><li>Low dose epiduraldon’t preload in severe PE</li><li>Combine spinal epidural</li></ul>
<h3><strong>Anti – Hypertensives:</strong></h3>
<h3><strong>* </strong><strong>A</strong><strong>ntenatal</strong><strong> Period:</strong></h3>
<ul><li>1st line – labetalol (C/I in Asthma).</li><li>2nd line – nifedipine (C/I with Mgso4).</li><li>3rd line – Methyldopa, (C/I in PP period).</li></ul>
<h3><strong>* </strong><strong>P</strong><strong>ostnatal</strong><strong>:</strong></h3>
<ul><li>Enalapril – Breast Feeding friendly.</li><li>Nifedipine/amlodipine.</li><li>Combination of enalapril + Nifedipine.</li><li>Add atenolol Labetalol to combination</li><li>Mildly exerted in breast milk.</li><li>Ask women to look for signs of drowsiness paler, Feeding problem in baby.</li><li>Check B.P of baby.</li></ul>
<p><strong>HELLP</strong> is a cause of 3 – 15% of Aki.</p>
<h3><strong>Recurrence of hypertension</strong></h3>', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2542ce6d', 't-mm-08-008', 'html', '<table><tbody><tr><td><strong>Recurre</strong><strong>nce</strong><strong>:</strong></td><td>In current/ previous pregnancy</td></tr><tr><td>In future pregnancy</td><td>HTN</td><td>Pre-eclampsia</td><td>Gest HTN</td></tr><tr><td>HTN</td><td>21%</td><td>20%</td><td>22%</td></tr><tr><td>Pre-eclampsia</td><td>14%</td><td>- 16% overall - birth before 34 weeks 33%<br/>- after 34 – 37 weeks 23%.</td><td>7%</td></tr><tr><td>Gest HTN</td><td>9%</td><td>6 – 12%</td><td>11 – 15%</td></tr><tr><td>Chronic HTN</td><td>4%</td><td>2%</td><td>3%</td></tr></tbody></table>', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-08-009', 'chap-mm-08-01', '9.LOW DOSE ASPIRIN + CALCIUM SUPPLEMENTATION FOR PREVENTION OF PRE – ECLAMPSIA', 'Detailed medical reference and study guide on 9.LOW DOSE ASPIRIN + CALCIUM SUPPLEMENTATION FOR PREVENTION OF PRE – ECLAMPSIA.', 9, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e1f0e607', 't-mm-08-009', 'html', '<ul><li>Pre – Eclampsia = 3 – 5%, 50,000 deaths/ year in the world.</li><li>Impaired placentation 8 – 18 weeks.</li></ul>
<h3><strong>Screening for </strong><strong>Pre – Eclampsia</strong><strong>:</strong></h3>
<p><em><strong>* History:</strong></em><em><strong> </strong></em><em>with 10% false positive detection</em></p>
<ul><li>Pre – Eclampsia detection 47%.</li><li>Gest Hypertension detection = 35%</li></ul>
<h3><em><strong>* History + MAP</strong></em><em><strong> (Mean Arterial Pressure)</strong></em><em><strong>:</strong></em></h3>
<ul><li>Pre – Eclampsia – 60%.10% false</li><li>G.H 40%positive</li></ul>
<h3><em><strong>* History + Pla</strong></em><em><strong>cental Mar</strong></em><em><strong>ke</strong></em><em><strong>r</strong></em><em><strong>s:</strong></em></h3>
<p>PLGF, PAPPA – A</p>
<ul><li>Early Pre – Eclampsia – 80%    10% false</li><li>Late Pre – Eclampsia 64%.          positive</li><li>G.H 39%.</li></ul>
<h3><em><strong>* History + MAP + UA Doppler + p</strong></em><em><strong>la</strong></em><em><strong>cen</strong></em><em><strong>tal ma</strong></em><em><strong>r</strong></em><em><strong>kers:</strong></em></h3>
<ul><li>Early Pre – Eclampsia 88.5%.    10% false</li><li>Late Pre – Eclampsia 46.7%     positive</li><li>G.H 35.5%</li></ul>
<h3><em><strong>* </strong></em><em><strong>Placental</strong></em><em><strong> </strong></em><em><strong>Biomarkers</strong></em><em><strong> in prediction of pre-Eclampsia:</strong></em></h3>
<ul><li>PLGF</li><li>S – Flt 1 =</li><li>PAPPA =</li><li>SEND =</li><li>VEGF =</li><li>HCG =</li><li>ADAM =</li></ul>
<h3><strong>Low dose Aspirin:</strong></h3>
<ul><li>More effective before 16 weeks</li><li>start after 12 weeks 75 – 150mg.</li><li>8% reduction in PTB.</li><li>14% reduction in neonatal death.</li><li>10% reduction in IUGR</li><li>17% reduction in Pre – Eclampsia</li></ul>
<h3><strong>Mechanism of Action of Aspirin:</strong></h3>
<p>Inhibits cyclooxygenase</p>
<p>Inhibit production of</p>
<p><em><strong>1. Prostacyclin</strong></em><em><strong>2. Thromboxane A2</strong></em></p>
<ul><li>Found in Endothelium       - Found in platelets</li><li>Cause Vasodilatation         - Vasoconstriction</li><li>Effects are reversible         - irreversible</li></ul>
<h3><strong>Ca</strong><strong>lcium</strong><strong> – Supplementation:</strong></h3>
<ul><li>After 20 weeks 1.5 – 2 g Elemental Calcium/day.</li><li>2 – 3 divided doses until delivery.</li><li>Target population – High risk for Pre – Eclampsia, Ca deficiency population.</li><li>Max dose 3000mg/day.</li></ul>
<h3><strong>Ca + Aspirin:</strong></h3>
<ul><li>Can be given simultaneously</li></ul>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-08-010', 'chap-mm-08-01', '10.HEMOPHILIA', 'Detailed medical reference and study guide on 10.HEMOPHILIA.', 10, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d7c2c33e', 't-mm-08-010', 'html', '<ul><li>X – linked recessive disorders:</li><li>Type A – Absent or reduced Factor VIII.</li><li>Type B – Absent or reduced Factor IX.</li><li>Male affected 50%.If female</li><li>Female carrier 50%.is carrier</li><li>50% has no previous history</li><li>Spontaneous mutation in 40 – 50% cases</li><li>More mutations in spermatogenesis than oogenesis</li><li>In maternal Grand Father.</li><li>Factor VIII: VWF &lt;0.7 is suggestive of carriership</li></ul>
<h3><strong>Types:</strong></h3>
<ul><li><em><strong>Mild:</strong></em> .06 – 0.40IU/mlbleeding after</li><li><em><strong>Mod:</strong></em> 0.01 – 0.5 trauma</li><li><em><strong>Severe:</strong></em> &lt; 0.01 – spontaneous bleeding in Joints and muscles.</li></ul>
<p><strong>Carriers:</strong>  risk of bleeding during invasive procedures, TOP, C/S, SVD when levels between 0.4 – 0.6.</p>
<p><strong>Neonate</strong><strong>s:</strong> Male at risk of ICH, ECH, iatrogenic haemorrhage.</p>
<h3><strong>Pre – </strong><strong>Pregnancy Management:</strong></h3>
<ul><li>Monitor levels before pregnancy.</li><li>Correct weight and iron deficiency =&gt;    ed bleeding risk.</li><li>Genetic counselling + genetic testing of partner.</li><li>Written informed consent before genetic Testing.</li></ul>
<h3><strong>ANC:</strong></h3>
<ul><li>MDT management of pregnancy</li><li><strong>P</strong><strong>renatal diagnosis</strong> – all carriers of severe hemophilia</li><li>9 weeks CFFDNA in all pts to determine sex.</li><li>If male fetus then determine hemophilia status by</li><li>1.CVS at 11 – 14 weeks.</li><li>2.Amniocentesis in 3rd</li></ul>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-51947b9f', 't-mm-08-010', 'image', '/uploads/content-images/maternal_mind_book/image95.emf', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-183e8b2d', 't-mm-08-010', 'html', '<ul><li>Male fetus – informed choices.</li><li>If PND not performed – consider as affected fetus.</li><li>Factor levels:</li><li>Female genderFemale genderFemale genderFemale genderCheck at booking, before invasive procedure and in 3rd   -( Target – 0.5I/ml)</li></ul>', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-79db8848', 't-mm-08-010', 'image', '/uploads/content-images/maternal_mind_book/image95.emf', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cf3a141e', 't-mm-08-010', 'html', '<ul><li>If treatment is given then target is 1U/ml.</li><li>MDT includes neonatologist and obstetrician.</li></ul>
<h3><strong>Acute Bleeding:</strong></h3>
<ul><li>Tranexamic acid all women</li><li>In combination of factor VIII if levels are &lt; 0.5.</li><li>Solely if &gt; 0.5.</li></ul>
<p>in all procedures until Bleeding settles.</p>
<h3><strong>Desmopressin</strong><strong> (DDAVP)</strong><strong>:</strong></h3>
<ul><li>DDAVP    level VIII but not IX via V2 receptors on endothelial cells.</li><li>Used in labor to    levels of factor VIII</li><li>S/C or I/V 0.3ug/kg, Repeat 12 – 24hrs, Risk of tachyphylaxis.</li><li>Avoid in HTN, pre – eclampsia.</li><li>Antidiuretic effect =&gt; hyponatremia – fits.</li><li>Fluid restriction to 1 lit/day/</li><li>Electrolyte monitoring.</li><li>Level monitoring before and after treatment.</li></ul>
<h3><strong>r Factor VIII:</strong></h3>
<ul><li>If DDVAP not effective, monitor levels before, after and 4 – 6 hours after infusion.</li></ul>
<h3><strong>Intrapartum Care Plan</strong><strong>:</strong></h3>
<ul><li>Written/ documented in advance of 37 weeks.</li><li>Anesthesia evaluation, Neonatologist informed.</li><li>ECV in Male not recommended.</li><li>In female ECV can be done.</li><li>Gender not known – avoid ECV.</li></ul>
<h3><strong>IPC:</strong></h3>
<ul><li>MOD discussed in MDT – target levels &gt;1 IU/ml</li><li><strong>affected Male Fetus/ unknown status.</strong></li><li>Elective C section @ 39 weeks with a clear Plan in case of spontaneous labor.</li><li>Consider Maternal Bleeding risks.</li><li><strong>Female gender or unaffected male</strong></li><li><em><strong>Vaginal delivery:</strong></em> spontaneous labor is preferred.</li><li>IOL if concerns regarding travel to specialist center.</li><li><em><strong>2</strong></em><em><strong>nd</strong></em><em><strong> Stage:</strong></em> Plan documented, involving senior obstetrician.</li><li>Avoid midcavity forceps, ventouse, FBS scalp Electrodes, Outlet or low Forceps can be used.</li><li>No Measures in case of Female fetus.</li><li>ICH more in Pre – Term Babies.</li></ul>
<h3><strong>Analgesics/ Anaesthesia:</strong></h3>
<ul><li>Regional Anaesthesia (target &gt; 0.5IU/ml) Neuraxial Hematoma – Neurological injury.</li><li>I/M injections avoided if levels &lt; 0.5IU/ml.</li><li>Anaesthesia evaluation by senior Anaesthetist @ 32 – 34 weeks after knowledge of VIII/IX levels.</li></ul>
<h3><strong>Haemostatic Management during labor/ Delivery:</strong></h3>
<ul><li>Levels &lt; 0.5IU/ml -&gt; treatment:</li><li>DDAVP to    VIII.</li><li>Factor IX concentrate.</li><li>Targets 1 IU/ml.</li><li>Tranexamic Acid:</li><li>Solely in low normal levels.</li><li>In combination with factor in low levels.</li></ul>
<p>Treatment as close as labor.</p>
<h3><strong>Post partum care</strong><strong>:</strong></h3>
<ul><li>Active 3rd stage of labour.</li><li>Maintain levels after labour</li><li>3 days after SVD.</li><li>5 days after C/S.</li><li>Tranexamic acid till lochia is minimal (21 – 58days carrier).</li><li>Thromboprophylaxis avoided if level &lt; 06, use UfH If it is required.</li></ul>
<h3><strong>PPH prophylaxis: </strong></h3>
<ul><li>Tranexamic acid 1g three times a day for 7 – 14 days (all Pts).</li></ul>
<h3><strong>Neonat</strong><strong>al Management:</strong></h3>
<ul><li>Cord blood sampling – results interpreted against age – adjusted ranges.</li><li>Repeat testing 3 – 6m0 of age in mild cases.</li><li>Oral vitamin K.affected</li><li>Cranial USG neonates.</li><li>MRI Skull – if S/S of ICH or ICH on USG.</li><li>Short term P0 prophylaxis – severe/ Moderate cases with traumatic delivery, Pre – Term birth and @   ed risk of bleeding.</li></ul>
<p>Female Baby =&gt; No testing required.</p>
<h3><strong>Target Levels:</strong></h3>
<ul><li>Antenatal = &gt; 0.5</li><li>Treatment given &gt; 1.</li><li>I/P &gt;1.</li><li>Procedures = &gt; 0.5.</li><li>PP = &gt; 0.5.</li><li>VTE prophylaxis &gt; 0.6.</li><li>I/M injections &gt; 0.5/</li><li>Regional Anaesthesia &gt; 0.5</li></ul>
<h3><strong>Fetal Effects of Hemophilia:</strong></h3>
<ul><li>Genetic Transmission.</li><li>ICH.</li><li>ECH.</li></ul>
<h3><strong>Matern</strong><strong>al Effects</strong><strong> of Hemophilia</strong><strong>:</strong></h3>
<ul><li>Risk of bleeding.</li><li>PPH</li><li>APH</li><li>Muscle and joint Bleeding is the Hallmark of Hemophilia.</li></ul>', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-08-011', 'chap-mm-08-01', '11.VWD', 'Detailed medical reference and study guide on 11.VWD.', 11, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-413e0c62', 't-mm-08-011', 'html', '<ul><li>Incidence : 1/ 10,000</li><li>Most common inherited bleeding disorder.</li><li>Less symptomatic more common 1/ 1000.</li><li>Menorrhagia is hallmark</li></ul>
<h3><strong>Type I:</strong></h3>
<ul><li>Partial Quantitative, Autosomal <strong>dominant.</strong></li><li>Variable penetrance/ Expressivity.</li><li>Low VWD 0.3 – 0.5 Iu/ml.</li><li>Severe VWD &lt; 0.3 IU/ml</li><li>Levels increase during pregnancy.</li><li>Manage in Obstetric unit.</li><li>Regional anaesthesia can be given</li><li>No neonatal testing of cord blood.</li><li>DDAVP is effective</li></ul>
<h3><strong>Type II:</strong></h3>
<ul><li>Qualitative – generally autosomal dominant except Type N.</li><li>Types:</li><li>2A</li><li>2B – thrombocytopenia.</li><li>2N – No recessive inheritance</li><li>2M.</li></ul>
<h3><strong>Type III:</strong></h3>
<ul><li>Absent VWF, autosomal recessive inheritance, more in consanguineous relations.</li><li>PND + genetic testing + counselling.</li><li>Riskier.</li><li>MDT.</li><li>DDAVP not effective, factor should be given.</li><li>Cranial USG in Neonates.</li><li>Neonatal Testing of cord blood</li><li>No regional anaesthesia.</li><li>No FBS, FSE, vacuum, mid cavity Forceps.</li></ul>
<h3><strong>M</strong><strong>aternal Risks</strong><strong> of Type II &amp; III &amp; severe Type I</strong><strong>:</strong></h3>
<ul><li>APH – 10times</li><li>P0 PPH – 15 – 30%.</li><li>S0 PPH – 25%.</li><li>Blood Tx = 5times</li><li>Mortality = 10times</li></ul>
<h3><strong>Neonatal</strong><strong> Concerns</strong><strong>:</strong></h3>
<ul><li>Type 2, 3 + severe forms of type 1.</li><li>Cord blood testing = Type 2,3 (risk of ICH, ECH)</li><li>Carnival USG = Type 3.</li><li>Short Term Prophylaxis type 3.</li><li>Oral vitamin K 2,3.</li><li>Mild VWD testing @ 6m0 of age.</li></ul>
<p><strong>Pre pregnancy + ANC</strong>MDT.</p>
<h3><strong>Check</strong></h3>
<ul><li>Bleeding phenotype.</li><li>Historical diagnosis.</li><li>Response to DDAVP.</li><li>VWF antigen level + activity + factor VIII</li><li>@ Booking 3rd , prior to invasive procedure.</li></ul>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9389c0d6', 't-mm-08-011', 'image', '/uploads/content-images/maternal_mind_book/image95.emf', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-947d6002', 't-mm-08-011', 'html', '<ul><li>Type I + normal VWF =&gt; std Management in pregnancy in liaison with hemophilia center (std obstetric care).</li><li>Type 2,3 severe I =&gt; specialist center in high risk obstetric (in center with expertise MDT).</li><li>Target Factor VIII + VWF Risto cetin co factor activity 0.5IU/ml.</li></ul>
<h3><strong>Hemostatic Support:</strong></h3>
<ul><li><em><strong>DDAVP:</strong></em></li><li>Avoid in 2B, III, with baseline level &lt; 0.15.</li><li>2B – Thrombocytopenia with DDAVP.</li><li>DDAVP    VWF  2 – 5-fold.</li><li>In responders: 0.3ug/kg of DDAVP.</li><li><em><strong>Plasma derived VWF </strong></em><em><strong>concentrate </strong></em><em><strong>replacement:</strong></em></li><li>Screening for transfusion related transmitted infections.</li><li>Vaccination Hep A &amp; B.</li><li>Contain VIII and VWF</li><li>Powder form has two types</li><li>High Purity.</li><li>Intermediate purity.</li><li>Slow bolus I/V.</li><li>VWF ag/ VWF: RCO consideration before VWF concentrate replacement as amount of VIII varies between different preparations.</li></ul>
<h3><strong>IPC + Ana</strong><strong>e</strong><strong>sthesia:</strong></h3>
<ul><li>MOD depends on obstetric indicators.</li><li>Measure levels of VWF near delivery Pre and Post treatment, after delivery or if labour is prolonged.</li><li>ECV, mid cavity forceps, vacuum, FSE, FBS, C/I in type 2,3.</li><li>Outlet or low forceps can be used.</li></ul>
<h3><strong>Prophylaxis for PPH:</strong></h3>
<ul><li>Tranexamic acid 1g I/V in low or normal VWF: RCO levels,</li><li>Desmopressin = close to delivery, can be given along or in combination with tranexamic acid.</li><li>Plt transfusion in 2B VWD</li><li>VWF replacement in 2B</li></ul>
<h3><strong>Regional Anaesthesia:</strong></h3>
<ul><li>Discuss Anaesthesia options with women and senior Anaesthetist</li></ul>
<h3><strong>Type I</strong></h3>
<ul><li>Regional anaesthesia is safe in Type I with normal level &gt; 0.5.</li></ul>
<h3><strong>Type II</strong><strong>:</strong></h3>
<ul><li>Can be given if &gt; 0.5IU/ml.</li><li>Hemostatic defect corrected.</li></ul>
<h3><strong>Type III:</strong></h3>
<ul><li>Avoid.</li><li>I/M injection can be given where VWF activity and VIII levels &gt; 0.5 IU/ml.</li></ul>
<h3><strong>PNC:</strong></h3>
<ul><li>Maintain VWF activity and factor VIII</li><li>3 days in SVD.</li><li>5 days in C/S.</li><li>Tranexamic acid 1g 3 – 4times/ day, 7 – 14days</li><li>Sometimes 2 – 3 weeks or more.</li><li>Thromboprophylaxis after correction of VWF RCO/VIII.</li><li>VWF concentrate required in type 3 for 3 weeks after delivery.</li><li>Average time for PPH 10 – 20 days.</li><li>COCP in P/P period    es VWF production.</li><li>Offer COCP if no other contraindication</li></ul>', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-08-012', 'chap-mm-08-01', '12.FACTOR XI DEFICIENCY', 'Detailed medical reference and study guide on 12.FACTOR XI DEFICIENCY.', 12, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b3f5f6cd', 't-mm-08-012', 'html', '<ul><li>Autosomal disorder:</li><li>Recessive.</li><li>Dominant.</li><li>Non-Jewish 1/1000,000.</li><li>Ashkenazi Jews:</li><li>Homozygous 0.2 – 0.5%.</li><li>Heterozygosity 8% - demonstrate bleeding tendency</li><li>Helps in amplification of coagulation process after initial thrombin formation.</li><li>Plasma level – poor co relation with bleeding.</li><li>Spontaneous bleeding – rare.</li><li>Bleeding after trauma.</li></ul>
<h3><strong>Heterozygote</strong><strong> clinical type</strong><strong>:</strong></h3>
<ul><li>XI, bleeding, tendency even with mild reduction.</li></ul>
<h3><strong>ANC:</strong></h3>
<ul><li><em><strong>Level Check:</strong></em></li><li>Booking, 3rd , prior to invasive procedure.</li></ul>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-013c796f', 't-mm-08-012', 'image', '/uploads/content-images/maternal_mind_book/image95.emf', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a77b7abc', 't-mm-08-012', 'html', '<ul><li>Levels don’t rise in pregnancy (usually).</li><li>Assess all women for compounding Factors, VWF, Plt dysfunction.</li><li><em><strong>e</strong></em><em><strong>d Risk of Bleeding:</strong></em></li><li>O blood group, bleeding phenotype</li><li>Other compounding factors like VWF, Plt dysfunction.</li><li><em><strong>Neonatal Risks:</strong></em></li><li>Minimal except homozygosity or compound heterozygote.</li><li>No ICH, No need for PND.</li><li><em><strong>Therapeutic Options:</strong></em></li><li>Tranexamic Acid</li><li>Factor XI concentrate</li><li>FFP</li><li>Tranexamic – never with factor XI concentrate =&gt; risk of thrombosis alone tranexamic acid is sufficient in most cases</li><li>FFP.</li><li>Factor XI – concentrate; risk of thrombosis in factor XI inhibitors.</li><li>rxIIa – can be used in inhibitors of XI</li><li>rxIIa use is off license, can be used carefully in low doses.</li></ul>
<h3>ANC, intrapartum and post-partum care:</h3>
<ul><li>factor XI or Tranexamic acid is not required antenatally unless an invasive procedure is undertaken or if there is bleeding following miscarriage or surgical procedure.</li><li>Delivery plan individualized</li><li>Prophylactic factor XI replacement in homozygous or compound heterozygous, previous history of bleeding.</li></ul>
<h3><strong>Central </strong><strong>Neura</strong><strong>xial</strong><strong> Anesthesia:</strong></h3>
<ul><li>Don’t in women with low f – XI with bleeding phenotype.</li><li>Phenotype is not clear.</li><li>Severe reduction in levels otherwise can be given.</li></ul>', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-08-013', 'chap-mm-08-01', '13.FIBRINOGEN DISORDERS', 'Detailed medical reference and study guide on 13.FIBRINOGEN DISORDERS.', 13, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f8935a9b', 't-mm-08-013', 'html', '<ul><li>Afibrinogenemia – recessive, 1/ 1000,000.</li><li>Hypofibrinogenemia – partial Qualitative/ quantitative, autosomal dominant</li><li>Dys fibrinogen – Qualitative, dominant.</li></ul>
<h3><strong>Risks: </strong></h3>
<ul><li>Afibrinogenemia –risk of ICH, PPH.</li><li>Hypofibrinogenemia- dysfunction of coagulation – thrombosis and pregnancy loss.</li></ul>
<h3><strong>Af</strong><strong>ibrinogen</strong><strong>emia</strong><strong>: </strong></h3>
<ul><li>If fibrinogen &lt; 0.3g/lit =&gt; prophylaxis with fibrinogen concentrate 50 – 100mg/kg – Twice/weeks, throughout the pregnancy</li><li>Target in pregnancy – 1g / lit</li><li>Labor + P/P = 1.5/lit for 3 days Post delivery.</li><li>Tranexamic acid in case of minor bleeding</li></ul>
<h3><strong>Hypo</strong><strong>fibrinogenemia:</strong><strong> </strong></h3>
<p><em><strong>         </strong></em><em><strong> </strong></em>Expectant Management.</p>
<h3><strong>Regional an</strong><strong>aes</strong><strong>thesia:</strong></h3>
<ul><li>NSAID, I/M injections</li><li>ECV, mid cavity forceps, FBS.AVOID</li><li>Ventose FSE.</li><li>Regional Anaesthesia</li><li>Fibrinogen replacement therapy is associated with thrombosis, so care is needed.</li></ul>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-08-014', 'chap-mm-08-01', '14.PLT FUNCTION DISORDERS', 'Detailed medical reference and study guide on 14.PLT FUNCTION DISORDERS.', 14, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-6194470f', 't-mm-08-014', 'html', '<ul><li>Pre pregnancy counselling in MDT</li></ul>
<h3><strong>B</strong><strong>ernard </strong><strong>Soul</strong><strong>ier</strong><strong> syndrome BSS:</strong></h3>
<ul><li>PLT adhesion receptor (GP – Ib – IX – V).</li><li>Epistasis, menorrhagia, oral bleeding.</li><li>Thrombocytopenia + large Plt.</li><li>Autosomal recessive, High in consanguineous relationships.</li><li>Heterozygous are asymptomatic</li></ul>
<h3><strong>Management:</strong></h3>
<ul><li>P0, See PPH, wound haematoma.</li><li>33% prophylactic Plt  transfusion prior to delivery/ C/S.</li><li>Tranexamic acid throughout labor and continue PP till lochia is healthy.</li><li>DDAVP – variable efficiency – helpful.</li><li>Regional anaesthesia avoided.</li></ul>
<h3><strong>Glanzmann </strong><strong>thrombocytopenia</strong><strong> GT.</strong></h3>
<ul><li>Pt function disorder, Autosomal recessive.</li><li>Severe bleeding tendency.</li><li>GP II b / IIIa.</li><li>DDAVP not effective,</li><li>PPH = 34%.</li><li>See = 24%.</li></ul>
<h3><strong>Management:</strong><strong> </strong></h3>
<p>-as in BSS</p>
<p>-Recombinant VII – Who has antibodies to GP II b/IIIa.</p>
<p>-PLT specific Ab @ booking, 28 weeks, 34 weeks.</p>
<h3><strong>Fetal:</strong></h3>
<ul><li>ICH due to alloimmunization.</li><li>FMU I/V immunoglobulins, steroids.</li><li>Amniocentesis</li><li><strong>A</strong><strong>lloimmunization</strong><strong> to Fetus</strong><strong>: </strong></li><li>Take all precautions to prevent ICH as other disorder.</li></ul>
<p>Plt transfusion to neonatal if Plt &lt;30x 9.</p>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9db2c1fc', 't-mm-08-014', 'image', '/uploads/content-images/maternal_mind_book/image97.png', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-e5038503', 't-mm-08-014', 'html', '<p>Table 32. Plt function disorder</p>', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ce63d52c', 't-mm-08-014', 'image', '/uploads/content-images/maternal_mind_book/image98.png', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
