INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-08-017', 'chap-mm-08-01', '17.SLE IN PREGNANCY', 'Detailed medical reference and study guide on 17.SLE IN PREGNANCY.', 17, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a1022b45', 't-mm-08-017', 'html', '<ul><li>25% among Monozygotic twins.</li><li>Women: Man, 10: 1</li><li>4/11 criteria for diagnosis</li></ul>
<h3><strong>Pregnancy counselling:</strong></h3>
<h3>Fertility reduction in SLE is rare except:</h3>
<ul><li>Ovarian failure due to cyclophosphamide.</li><li>End stage renal disease.</li><li>NSAIDS</li></ul>
<h3><strong>Assessment of </strong><strong>disease </strong><strong>Activity.</strong></h3>
<ul><li><em><strong>CVS =</strong></em> pulmonary HTN, VHD, Cardiomyopathy by Echo.</li><li><em><strong>Resp</strong></em><em><strong>iratory</strong></em><em><strong> =</strong></em> Pulmonary fibrosis by X – RAY, CT, lung function test.</li><li><em><strong>Renal =</strong></em> urine dipstick, protein: Creatinine ratio haematuria, HTN, RFT’s.</li><li><em><strong>H</strong></em><em><strong>a</strong></em><em><strong>ematological =</strong></em> thrombocytopenia by FBC.</li><li><em><strong>Immunological =</strong></em> APLA screening, Anti ds DNA, anti-Ro/La Ab, complement C3/C4 levels.</li><li><em><strong>APLA =</strong></em> 30% pts of SLE are APLA +ve.</li></ul>
<h3><strong>Avoid conception:</strong></h3>
<ul><li>Active disease.</li><li>Pulmonary HTN, 40% mortality, 4.2% incidence among SLE, most cases are mild &lt; 40 mmHg pressure.</li></ul>
<h3><strong>TOP</strong>: <strong>Indications</strong></h3>
<ul><li>Uncontrolled HTNDespite optimal</li><li>Worsening RFT’SPharmacological Treatment</li></ul>
<h3><strong>O</strong><strong>bstetric</strong><strong> Management:</strong></h3>
<ul><li>Positive Anti RO/LA, APLA =&gt; high risk – MDT.</li><li>Stable disease = 4 weekly review of disease activity and regular assessment of fetal Growth, B.P, proteinuria.</li><li>Anti RO/LA =&gt; Cardiac assessment @ 18 – 20 weeks.</li><li>Fetal Echo in +ve anti RO/LA antibodies.</li><li>@ 18 – 20 weeks and then FHR monitoring.</li></ul>
<h3><strong>Features</strong><strong>pregnancy – related</strong><strong>lupus activity</strong></h3>
<p>Anemia- physiologicalanemia of</p>
<ul><li>Iron deficiencychronic disease</li></ul>
<p>Protein urea- Pre-eclampsianephritis with haematuria + castpositive.</p>
<h3><strong>Differe</strong><strong>nce between Pre-eclampsia</strong><strong> &amp; lupus.</strong></h3>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-a35de292', 't-mm-08-017', 'html', '<table><tbody><tr><td><strong>Features</strong></td><td><strong>Pre-eclampsia</strong></td><td><strong>Lupus nephritis</strong></td></tr><tr><td>Proteinuria</td><td>+</td><td>+</td></tr><tr><td>Haematuria</td><td>-</td><td>+</td></tr><tr><td>Red cell cast</td><td>-</td><td>+</td></tr><tr><td>Lupus disease activity</td><td>-</td><td>+</td></tr></tbody></table>', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-12b6b66e', 't-mm-08-017', 'html', '<p><em><strong>Definitive:</strong></em> Renal Biopsy C/I in pregnancy.</p>
<p><em><strong>Management:</strong></em> Same as Gest HTN &amp; Pre-eclampsia.</p>
<p>In MDT setting</p>
<h3><strong>SLE Flare</strong></h3>
<ul><li>More in 2nd Half of Pregnancy</li></ul>
<h3><strong>Fetal </strong><strong>Management</strong><strong>:</strong></h3>
<ul><li>USG for IUGR: Uterine Artery Doppler@ 20 weeks.</li><li>¼ IUGR, 35% in lupus nephritis.</li><li>Echo: with Anti RO/LA Ab or cardiac abnormalities on USG.</li><li>Persistent Bradycardia 60 – 80   congenital heart</li><li>bpm between 18 – 28 weeks     block 2-3% of Anti                                             RO Anti LA</li><li>Recurrence is 16%</li></ul>
<h3><strong>Neonatal Lupus: </strong></h3>
<ul><li>After UV exposure 2 weeks after birth up to 3 – 6weeks</li><li>rarely Neonatal lupus with heart block.</li></ul>
<h3><strong>Drugs:</strong></h3>
<ul><li><em><strong>Give:</strong></em></li><li>Steroid: don’t cross placenta</li><li>prednisolone</li><li>Hydrocortisone</li><li>Methyl prednisolone.</li><li>Azathioprine</li><li>NSAIDS</li><li>Cyclosporine.</li><li>Hydroxychloroquine.</li><li><em><strong>Don’t Give:</strong></em></li><li>Steroid: Cross placenta</li><li>Dexamethasone.</li><li>Betamethasone.</li><li>Methotrexate</li><li>Cyclosporine.</li><li>Mycophenolate mofetil.</li></ul>', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-08-018', 'chap-mm-08-01', '18.APPENDICITIS IN PREGNANCY', 'Detailed medical reference and study guide on 18.APPENDICITIS IN PREGNANCY.', 18, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0fa08e1d', 't-mm-08-018', 'html', '<ul><li>1/800 suspected cases of appendicitis in pregnancy</li><li>1/800-1/1500 confirmed cases of appendicitis in pregnancy.</li><li>Uterus enlarges =&gt; upward pushing of abdominal wall =&gt; absent classical signs, Rt lower Quadrant pain only in 75%.</li><li>Abdominal Guarding = 50%.</li></ul>
<h3><strong>Investigations</strong>:</h3>
<ul><li>CBC leukocytosis</li><li>CRP.</li><li>USG:</li><li>Sensitivity 67 – 100%.</li><li>Specificity, 83 – 96%.</li><li>CT – avoid.</li><li>MRI if USG is inconclusive.</li></ul>
<h3><strong>Management:</strong></h3>
<ul><li>Fetal loss:</li><li>Simple appendicitis 1.5%.</li><li>Generalized peritonitis 6%.</li><li>Perforated 36%.</li><li>Lower index of suspicion.</li><li>35% Negative laparotomies.</li><li>I/OP normal appendix =&gt; remove.</li></ul>
<h3><strong>Incision:</strong></h3>
<ul><li>Transverse over Max tenderness.</li><li>Lower midline (if diagnosis is not confirmed).</li><li>Laparoscopy – safe in all , can be done up to 20 weeks</li></ul>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b2564205', 't-mm-08-018', 'image', '/uploads/content-images/maternal_mind_book/image95.emf', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-196bdc07', 't-mm-08-018', 'html', '<h3><strong>Ch</strong><strong>ronic</strong><strong> appendicitis:</strong></h3>
<ul><li>Walled of appendicitis.</li><li>Medical treatment F/B definitive treatment after pregnancy.</li><li>Prolong symptoms with conservative treatment.</li></ul>
<h3><strong>An</strong><strong>a</strong><strong>esthesia:</strong></h3>
<ul><li>Regional safe.</li><li>General with risks.</li><li>Desaturation in pregnant women within 3 min as compared to non-pregnant 9 min.</li><li>Tocolysis not required (GA is tocolytic).</li><li>FHR after 24 hours (before &amp; after procedure).</li><li>Opiates, NSAIDS up to 32 weeks.</li><li>Thromboprophylaxis till admission.</li><li>Antibiotics are given.</li></ul>
<h3><strong>D/D:</strong></h3>
<ul><li>Ectopic pregnancy</li><li>Gastroenteritis</li><li>Miscarriage</li><li>Musculoskeletal.</li><li>Pyelonephritis.</li><li>HELLP.</li><li>Abruption.</li><li>Chorioamnionitis – occult-chorio with intact Membranes – listeriosis.</li><li>Ovarian vein thrombosis.</li></ul>
<h3><strong>Effect of Pregnancy:</strong></h3>
<ul><li>1st  = all/none.</li></ul>', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
