INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-896522bd', 't-mm-09-008', 'image', '/uploads/content-images/maternal_mind_book/image123.png', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1aaf6158', 't-mm-09-008', 'html', '<ul><li><em><strong>Dual infection:</strong></em></li><li>CMV + HIV</li><li>High CNS disease progression &amp; HIV progression</li><li>Treatment should be given for CMV.</li></ul>
<h3><strong>Manifestations:</strong></h3>
<ul><li>Most – asymptomatic.</li><li>15% hearing loss.</li><li>10% symptomatic.</li><li>Hepatosplenomegaly.</li><li>Chorioretinitis.</li><li>Petechial purpura, jaundice.</li><li>Microcephaly.</li><li>SGA.</li></ul>
<h3><strong>Treatment:</strong></h3>
<ul><li>Ganciclovir protects against hearing loss and developmental delays.</li><li>Oral valacyclovir (20% people got reaction) it reduces risk of transmission to baby.</li><li>Hyper immunoglobulin – investigational.</li><li>Vaccination:</li><li>Under trial.</li><li>Delivery:</li><li>According to obstetric indications.</li><li>Patient education:</li><li>To all women.</li><li>B.F:</li><li>Safe except immune compromised.</li></ul>', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-09-009', 'chap-mm-09-01', '1.8.LISTERIA', 'Detailed medical reference and study guide on 1.8.LISTERIA.', 9, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-79aff780', 't-mm-09-009', 'html', '<ul><li>Listeria monocytogenes.</li><li>Associated with miscarriage and PTL.</li><li>Ed risk in:</li><li>Pregnant women.</li><li>Neonate.</li><li>Elderly.</li><li>Immunocompromised.</li><li>Maternal infection:</li><li>Placental infection =&gt; fetal septicemia</li><li>Asymptomatic.</li><li>Abscess formation (classic pathology).</li><li>Malaise, fever, chills, pharyngitis (infectious mononucleosis type).</li><li>Fever, headache, URTI (influenza type).</li><li>High grade spiking fever, backache (typhoid like).</li><li>Fever, musculoskeletal pain, nausea, vomiting, Diarrhea (febrile gastroenteritis type).</li></ul>
<h3><strong>Complications:</strong></h3>
<h3><strong>Maternal</strong></h3>
<ul><li>Sepsis.</li><li>Meningitis</li><li>Encephalitis</li><li>Cerebral abscess.</li><li>Brain abscess.</li></ul>
<h3><strong>Fe</strong><strong>tal</strong></h3>
<ul><li>IUD.</li><li>Congenital infection is fatal.</li></ul>
<h3><strong>Fetal listeria:</strong></h3>
<ul><li><em><strong>Early Onset:</strong></em></li><li>Within 2 days of birth.</li><li>Acquired from placenta.</li><li>Presents with septicemia and meningitis.</li><li><em><strong>Late onset:</strong></em></li><li>After 5 days of birth.</li><li>Acquired during child birth through birth canal.</li><li>Presents with meningitis.</li></ul>
<h3><strong>Diagnosis:</strong></h3>
<ul><li>Mother: blood culture, gram staining.</li><li>Baby: urine, amniotic fluid</li></ul>
<h3><strong>Culture</strong></h3>
<ul><li>Difficult to isolate from tissues.</li><li>Can be isolated from body fluids.</li></ul>
<h3><strong>Treatment:</strong></h3>
<ul><li>I/V ampicillin + gentamycin.</li><li>If allergic =&gt; Then trimethoprim/ sulfamethoxazole or Erythromycin.</li><li>Avoid cheese, don’t reheat left over food.</li></ul>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-09-010', 'chap-mm-09-01', '1.9.TOXOPLASMOSIS', 'Detailed medical reference and study guide on 1.9.TOXOPLASMOSIS.', 10, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-f9943824', 't-mm-09-010', 'html', '<ul><li>2/1000 pregnancies in UK.</li><li>Recurrence in HIV mothers.</li><li>Parasitemia within 3 weeks.</li></ul>
<h3><strong>Risk of congenital </strong><strong>sequalae &amp; complications</strong><strong>:</strong></h3>
<ul><li>Early = 85%.</li><li>Late = 10 – 80%.</li></ul>
<h3><strong>Mother to child transmission:</strong></h3>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d00fb5fa', 't-mm-09-010', 'html', '<table><tbody><tr><td><strong>trimester</strong></td><td><strong>CMV</strong></td><td><strong>Risk of </strong><strong>Toxo</strong></td></tr><tr><td>1st</td><td>40%</td><td>10%</td></tr><tr><td>2nd</td><td>40%</td><td>25%</td></tr><tr><td>3rd</td><td>80%</td><td>&gt; 85%</td></tr></tbody></table>', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1ad2a0a3', 't-mm-09-010', 'html', '<h3><strong>Toxo Triad:</strong></h3>
<ul><li>Intra cerebral calcifications.</li><li>Hydrocephaly.</li><li>Chorioretinitis.</li></ul>
<h3><strong>Diagnosis:</strong></h3>
<ul><li>Routine screening not recommended.</li><li>Serial USG to detect markers</li><li>Ascites.</li><li>Hepatosplenomegaly.</li></ul>
<h3><strong>Tests:</strong></h3>
<ul><li>ELIZA = enzyme – linked immune filtration assay.</li><li>PCR of amniotic fluid is highly accurate.</li></ul>
<h3><strong>Implications:</strong></h3>
<ul><li>Miscarriages.</li><li>Ascites/ hepatosplenomegaly.</li><li>Chorioretinitis.</li><li>Hydrocephaly.</li><li>Brain tissue calcification.</li><li>Visual impairment of fetus.</li></ul>
<h3><strong>Management:</strong></h3>
<ul><li>Antiparasitic – prevent fetal damage after transmission.</li><li>Not possible to eradicate.</li><li>TOP is an option.</li><li>Spiramycin to prevent congenital infections.</li><li>Sulphadiazine/ pyrimethamine given only if infection is confirmed (can be toxic).</li></ul>', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-09-011', 'chap-mm-09-01', '1.10.RUBELLA', 'Detailed medical reference and study guide on 1.10.RUBELLA.', 11, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-cc057fd8', 't-mm-09-011', 'html', '<ul><li>P0 Rubella</li><li>16/52 weeks – substantial.</li><li>Top</li><li>16 – 20 weeks – minimal risk</li><li>Follow up</li><li>After 20 weeks – no risk</li><li>Reassure.</li></ul>
<h3><strong>Congenital Rubella symptoms:</strong></h3>
<ul><li>Sensory neural deafness.</li><li>PDA, VSD.</li><li>Eye lesions, cataract, micro Ophthalmia.</li><li>Microcephaly.</li><li>Mental retardation.</li></ul>
<h3><strong>Implications of Rubella to Fetus/ Neonate:</strong></h3>
<ul><li>SN – deafness.</li><li>DM.</li><li>Thyroid disease.</li><li>GH deficiency.</li><li>Vascular effects</li><li>encephalitis.</li></ul>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-09-012', 'chap-mm-09-01', '1.11.SYPHILIS', 'Detailed medical reference and study guide on 1.11.SYPHILIS.', 12, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-99f41b65', 't-mm-09-012', 'html', '<ul><li>70 cases/ million deliveries.</li><li>Treponema pallidum.</li><li>Transmission:</li><li>Direct contact with lesion.</li><li>Vertical transmission.</li><li>Universal screening.</li></ul>
<h3><strong>Course of syphilis:</strong></h3>
<ul><li><em><strong>Early:</strong></em></li><li>P0: maculopapular rash + regional lymphadenopathy 10 days – 3m0.</li><li>Chancre, anogenital region, hard – indurated.</li><li>Secondary: untreated primary lesions.</li><li>25% sec syphilis after 4 – 10 weeks.</li><li>Multisystem involvement.</li><li>Rash + generalized lymphadenopathy.</li><li><em><strong>Latent Asymptomatic:</strong></em></li><li>Early – within 2 years.</li><li>Late – after 2 years.</li><li><em><strong>Late:</strong></em></li><li>Tertiary, Quarterly.</li><li>Gumas, system involvement:</li><li>CVS</li><li>CNS</li><li>Tabes dorsalis</li><li>General paresis.</li></ul>
<h3><strong>Diagnosis:</strong></h3>
<ul><li>Best test: TPHA, EIA.</li><li>Screening: VDRL.</li><li>Microscopic identification.</li></ul>
<h3><strong>USG:</strong></h3>
<ul><li>Early onset SGA:</li><li>TORCH screening.</li><li>Karyotyping.</li><li>FGR.</li><li>Brain:</li><li>Calcification.</li><li>Hydrocephaly.</li><li>Hydro anencephaly</li><li>Microcephaly.</li><li>GI:</li><li>Abnormal liver, spleen, bowels.</li><li>Ascites, hepatosplenomegaly.</li></ul>
<h3><strong>Congenital syphilis:</strong></h3>
<ul><li>Hydrops.</li><li>Nasal bone depressed, saddle nose.</li><li>Rash.</li><li>Hepatosplenomegaly.</li><li>Petechial rash.</li><li>Weinberger sign.</li></ul>
<h3><strong>Neonatal:</strong></h3>
<ul><li>Untreated – 50% dies.</li><li>Frontal bossing.</li><li>Saddle nose.</li><li>Interstitial keratitis.</li><li>Rhagades.</li><li>Perforated hard palate.</li><li>Hutchinson teeth.</li><li>Mulberry molar.</li><li>Saber shins.</li></ul>
<h3><strong>Fetal implications:</strong></h3>
<ul><li>Before 16 weeks – rare.</li><li>Miscarriage.</li><li>Still birth.</li><li>Neonatal death, disease or latent infection.</li><li>Untreated syphilis =&gt; 50% loss.</li></ul>
<h3><strong>Treatment of syphilis:</strong></h3>
<ul><li>Non – pregnant.</li><li>Pregnant.</li><li><em><strong>Non – pregnant:</strong></em></li><li><strong>Early:</strong></li><li>Benzathine penicillin G 2.4MU I/m x Stat single dose.</li><li>Amoxicillin 2mg P/o TDS</li><li>+ probenecid 500mg QDS</li><li>Ceftriaxone 2g I/M or I/V 10 – 14 days.</li><li><strong>Pregnancy:</strong></li><li><strong>Early syphilis:</strong></li></ul>
<p>Up to 28 days.After 28 days.</p>
<p>Penicillin G 2.4MU I/m.double dose</p>
<p>Single dose.Day 1</p>
<p>Day 8</p>
<h3><strong>Late syphilis</strong><strong> in pregnancy</strong><strong>:</strong></h3>
<ul><li>Late latent/Gumas/CVS/CNS.</li><li><strong>Doses</strong></li><li>Day 1, 8, 15.</li><li><strong>Neurosyphilis</strong></li><li><strong>Procaine</strong><strong> penicillin</strong> G</li><li>1.8 – 2.4 MU OD<strong>14 days.</strong></li><li>Plus</li><li><strong>Probenecid 500mg QDS.</strong></li><li>Benzyl Penicillin</li><li>10.8 – 14.4 daily.</li><li>1.8 – 2.4 I/V every 4 hours for 14 days.</li></ul>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-09-013', 'chap-mm-09-01', '1.12.PARVOVIRUS', 'Detailed medical reference and study guide on 1.12.PARVOVIRUS.', 13, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-133b6d0d', 't-mm-09-013', 'html', '<ul><li>Incubation period 4 – 14 days.</li><li>DNA – virus single stranded DNA.</li><li>Spontaneous replication in diving cells (S – phase).</li><li>Replicate and inhibit CFU &amp; cause lysis of human erythroid progenitor cells.</li></ul>
<h3><strong>Transmission:</strong></h3>
<ul><li>Droplets borne:</li><li>50 – 90% house hold contact.</li><li>20 – 30% in school staff.</li></ul>
<p><strong>Out Breaks: </strong>in spring.</p>
<p>50% of child bearing are immune.</p>
<ul><li>Vertical transmission 30% (so TOP not indicated).</li><li>1% of susceptible individuals are infected /year, 1 infection /400 pregnancy, 23 times higher during epidemics.</li></ul>
<h3><strong>Fetal risks:</strong></h3>
<ul><li>Loss rate 9% highest in 2nd .</li></ul>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
