INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-ebedbf0b', 't-mm-09-013', 'html', '<table><tbody><tr><td><strong>Syphilis</strong></td><td><strong>Parvovirus</strong></td></tr><tr><td>Still birth + Hydrops<br/>Placentomegaly<br/>Petechia all over skin<br/>VDRAL/RPR = acute syphilis<br/>@ 14 weeks = 40 – 50% infection</td><td>Still birth + Hydrops<br/>No palcentomegaly<br/>No petechial<br/>School out break<br/>80% poly arthritis in mother.</td></tr></tbody></table>', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-0aca05ef', 't-mm-09-013', 'html', '<h3><strong>Important facts about perinatal infections:</strong></h3>
<ul><li>Maculopapular rash on palms and soles and periostitis =&gt; <strong>syphilis</strong>.</li><li>Hydrocephaly, Intracerebral calcification, chorioretinitis=&gt; <strong>Toxo</strong><strong>plasmosis</strong> treatment sulfadiazine + leucovorin.</li><li>Cataract, SN deafness VSD, PDA, extramedullary hematopoiesis =&gt; <strong>rubella</strong> B/L hearing loss.</li><li>Microcephaly, PV calcification, deafness    Plt, petechia =&gt; <strong>CMV</strong> unilateral deafness treatment ganciclovir.</li><li>Limb hypoplasia, cutaneous lesions =&gt; <strong>v</strong><strong>aricella</strong>.</li><li>Still born + petechial rash = <strong>listeria</strong>.</li><li>EONNS + maternal cheese intake = <strong>listeria</strong>.</li><li>Most common cause of EONNS = <strong>GBS</strong>.</li><li>2nd most common cause of EONNS= <strong>listeria</strong>.</li><li><strong>CMV</strong> transmission 1st &amp; 2nd = 40%.</li></ul>', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
