INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-d9320902', 't-mm-09-013', 'html', '<ul><li><strong>CMV</strong> recent infection = low avidity.</li><li><strong>CMV</strong> infection = high avidity.</li></ul>', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-09-014', 'chap-mm-09-01', '1.13.HEMOPHILUS INFLUENZAE', 'Detailed medical reference and study guide on 1.13.HEMOPHILUS INFLUENZAE.', 14, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-831cdaf7', 't-mm-09-014', 'html', '<ul><li>G – negative Aerobic bacilli.</li><li>Commensal of vaginal flora can cause:</li><li>Chorioamnionitis.</li><li>Endometritis.</li><li>Neonatal infection.</li><li>Diagnosis = culture / ELIZA.</li><li>Hemophiles Ducreyi = STD, chancroid</li></ul>
<h3><strong>Cause:</strong></h3>
<ul><li>PTB.</li><li>LBW.</li></ul>
<h3><strong>Treatment in Pregnancy:</strong></h3>
<ul><li>Azithromycin.</li><li>Erythromycin.<strong>Ch</strong><strong>anc</strong><strong>roid.</strong></li><li>Ceftriaxone.</li></ul>
<p>H – Influenza: cephalosporin.</p>
<p>Annual vaccination recommended by WHO.</p>
<p>Vaccine safe in pregnancy &amp; B.F.</p>
<h3><strong>H1N1:</strong></h3>
<ul><li>RNA virus.</li><li>Infect birds and mammals.</li><li>Transmission by aerosol + direct contact.</li><li>Neuraminidase is involved in release of new viruses from infected cells.</li></ul>
<h3><strong>   </strong><strong>Treatment:</strong></h3>
<p>Oseltamivir- Inhibit neuraminidase + halt viral</p>
<p>Zanamivirreplication.- More effective if started within few hours of onset of symptoms.- Licensed for use within 48 hours of symptoms onset and can be given  within 7 days.- Duration of symptoms by 11.5days.-   Risk of complications</p>
<h3><strong>PEP:</strong></h3>
<p>Oseltamivir within 48 hours of exposure.</p>
<p>Zanamivir within 36 hours of exposure.</p>
<h3><strong>Prevention:</strong></h3>
<ul><li>Vaccination pander mix – yearly.</li><li>Avoidance of exposure.</li><li>Antiviral prophylaxis in case of exposure.</li><li>Severe disease =&gt; referral to hospital.</li></ul>
<h3><strong>Influenza:</strong></h3>
<ul><li>Fever, myalgia, SOB, cough.</li></ul>
<p><strong>O/E</strong>   reduced air entry, coarse crackles @ base.</p>
<p><strong>CXR</strong> one lobe is collapsed / consolidation throughout both lungs.</p>
<h3><strong>Atypical pneumonia</strong>:</h3>
<ul><li>Fever, myalgia, SOB, cough.</li><li>Examination same as influenza</li></ul>
<p><strong>C</strong><strong>XR:</strong> lower lobe collapse/ consolidation throughout both lungs’ sputum negative for gram staining and culture negative.</p>
<h3><strong>Streptococcus Pneumonia:</strong></h3>
<ul><li>Fever, SOB, cough.</li></ul>
<p><strong>O/E</strong>     air entry + coarse crept @ base.</p>
<p><strong>CXR </strong>lobe consolidation/ collapse.</p>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-09-015', 'chap-mm-09-01', '2.MATERNAL SEPSIS DURING & FOLLOWING PREGNANCY', 'Detailed medical reference and study guide on 2.MATERNAL SEPSIS DURING & FOLLOWING PREGNANCY.', 15, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-2d7ba71f', 't-mm-09-015', 'html', '<h3><strong>WHO</strong><strong> definition</strong><strong> of </strong><strong>Sepsis</strong><strong>:</strong></h3>
<ul><li>Organ dysfunction resulting from infection during pregnancy, child Birth, Post abortion or post-partum period.</li></ul>
<h3><strong>Septic shock:</strong></h3>
<ul><li>Persistent hypotension, requiring vasopressor to maintain an adequate B.P (MAP 65mmhg or more). Alongside an     increase in serum lactate &gt;2mmol despite adequate volume replacement.</li></ul>
<h3><strong>Risk Factors:</strong></h3>
<h3><strong>Maternal:</strong></h3>
<ul><li>Obesity</li><li>Impaired glucose tolerance.</li><li>Anemia.</li><li>DM</li><li>Age &gt; 35.</li><li>GAS in contact.</li><li>GBS carriage.</li><li>Pelvic infection.</li></ul>
<h3><strong>Obs</strong><strong>tetric</strong><strong> </strong><strong>Risk</strong><strong> Factors:</strong></h3>
<ul><li>SROM.</li><li>Amniocentesis.</li><li>Vaginal delivery.</li><li>C/Section.</li><li>Cervical cerclage.</li></ul>
<h3><strong>Importa</strong><strong>nt one lin</strong><strong>er:</strong></h3>
<ul><li>Most common infection = pneumonia 44%.</li><li>2nd most common = UTI 20%.</li><li>Most common agent = E. coli.</li><li>2nd most common = GBS – lesser mortality than GAS.</li><li><em><strong>GAS</strong></em> commonly present within 12 hours of abortion/ Birth with persistent Bleeding and Pain + feeling unwell.</li><li>GAS =&gt; increased mortality.</li><li>0.03 – 0.06% have perineal colonization with GAS &amp; are Asymptomatic, vaginal discharge is often watery, leukocytes are destroyed by GAS leucocidins and not offensive.</li><li><em><strong>Chorioam</strong></em><em><strong>n</strong></em><em><strong>i</strong></em><em><strong>on</strong></em><em><strong>itis</strong></em><em><strong> </strong></em>= mixed infection.</li><li><em><strong>UTI, cerclage, PPROM</strong></em> = coliform bacteria.</li></ul>
<h3><strong>Clinical symptoms, Signs &amp; </strong><strong>Risk</strong><strong> Factor:</strong></h3>
<p><em><strong>Sepsis screening Tool =&gt; Acute </strong></em><em><strong>Assessment</strong></em><em><strong>.</strong></em></p>
<ul><li>Start this chart when patient looks unwell or MEOW has triggered.</li><li><em><strong>R.F:</strong></em></li><li>Impaired immunity.</li><li>Recent trauma.</li><li>Indwelling lines.</li><li>Could it be due to infection=&gt;<strong>No</strong> =consider other diagnosis.</li></ul>
<p><em><strong>YES</strong></em></p>
<ul><li>Any <strong>Red Flag:</strong></li><li>Altered mental state</li><li>yesyesyesyesyesyesyesyesSystolic B.P &lt; 90 or Start <strong>Sepsis six:</strong></li><li>Drop &gt; 40mg.       <strong>YES</strong>a. Ensure senior</li><li>HR &gt; 130.review.</li><li>R.R &gt; 25.b. Oxygen if</li><li>Need oxygen to keeprequired</li><li>Spo2 &gt; 92%.c. I/V line; take</li><li>Non blanching rash/blood.</li><li>Molted/Ashen/cyanotic.d. Give A/B</li><li>Lactate &gt; 2mmol/lit.e. Give I/V fluids</li><li>Not passed urine in 18 hrs.f. Monitor.</li></ul>
<p><em><strong>NO</strong></em></p>
<ul><li>Any <strong>Amber Flag:</strong></li><li>Acute deterioration</li><li>In functional capacity.Further</li><li>RR = 21 – 24/min.required.</li><li>HR = 100 – 129/min.Review:</li><li>Systolic B.P = 91 – 100mnHg.- Send</li><li>Any invasive procedure inblood.</li><li>6wks (C/S, SVD, miscarriage).- Senior</li><li>Temperature &lt; 360C.<strong>YES</strong>review</li><li>DM or GDM.within 1</li><li>Close contact with GAS.hour</li><li>Prolonged ruptured membranes.</li><li>Bleeding/ wound infection.</li><li>Offensive vaginal discharge.</li><li>Fetal tachycardia &gt; 160/min.</li><li>Behavioral/ Mental change.</li></ul>
<p><em><strong>NO</strong></em></p>
<p>Routine care.</p>
<h3><strong>Investigations:</strong></h3>
<h3><strong>Routine blood Tests:</strong></h3>
<ul><li>All PTs suspected of sepsis</li><li>CBC:</li><li>12 x 109.</li><li>&lt; 4 x 109.</li><li>10% immature cells</li><li>CRP.</li><li>Clotting screen.</li><li>Urea and electrolytes.</li><li>LFT’S.</li><li>Creatinine.</li><li>Venous blood gases.</li></ul>
<h3><strong>Serum lactate levels:</strong></h3>
<ul><li>during labor and Haemorrhage.</li><li>2 mmol =&gt; senior review.</li><li>Repeat levels.</li><li>I/V Fluids.</li><li>4 = severe sepsis.</li></ul>
<h3><strong>Blood cultures:</strong></h3>
<ul><li>All pts.</li><li>2 set of samples before antibiotics.</li><li>Send samples and start empirical therapy, don’t wait for results.</li><li>Start with Broad Spectrum Antibiotics.</li></ul>
<h3><strong>HSV:</strong></h3>
<ul><li>Blood for PCR immediately.</li><li>If viral sepsis is suspected, start antiviral immediately after samples.</li></ul>
<h3><strong>SARs COVID – 2:</strong></h3>
<ul><li>If suspected.</li></ul>
<h3><strong>Throat swabs:</strong></h3>
<ul><li>If symptoms of tonsillitis.</li></ul>
<h3><strong>Pre – moisture nose swabs:</strong></h3>
<ul><li>To check MRSA statuses.</li></ul>
<h3><strong>Procalcitonin</strong><strong>:</strong></h3>
<ul><li>Differentiate between viral and bacterial sepsis.</li></ul>
<h3><strong>Influenza:</strong></h3>
<ul><li>Vaccination    mortality.</li><li>Send sample if suspected.</li><li>Affect women with BMI &gt; 30.</li><li>Pulmonary Haemorrhage occurs in influenza infection.</li><li>Early birth recommended in influenza infection.</li><li><strong>Points to be noted in History:</strong></li></ul>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8971d219', 't-mm-09-015', 'html', '<table><tbody><tr><td><strong>History</strong></td><td><strong>Symptoms/ features.</strong></td><td><strong>Organism suspected</strong></td></tr><tr><td>Febrile illness.</td><td>Chills, Myalgia rigors.</td><td>Wound/Rash =&gt; staphylococcus, streptococcus.<br/>UTI/ Catheterization =&gt; Gram positive.<br/>Flue =&gt; influenza.<br/>Foreign travel =&gt; SARS – COV-2, Adenovirus, Malaria, Homorganic fever.</td></tr><tr><td>Contact with GAS</td><td>Tonsillitis, impetigo.<br/>Cellulitis, vomiting.<br/>Rapid deterioration.<br/>Severe pain</td><td>GAS</td></tr><tr><td>Skin infection or contact with boil/ Abscess.</td><td>Abscess, mastitis.<br/>Infected Scars.<br/>Purulent discharge.</td><td>PVL producing staph aureus.</td></tr><tr><td>Dysuria flank pain fever</td><td>Dysuria suggesting UTI</td><td>&nbsp;</td></tr><tr><td>Urinary retention</td><td>Acute retention.<br/>Vulval/ sacral Pain.</td><td>HSV.</td></tr><tr><td>I/V misuse.</td><td>Vasculitis lesion.<br/>Endocarditis.</td><td>GAS.<br/>PVL producing s. Aureus.<br/>HIV, HBV, HCV.</td></tr><tr><td>Gastroenteritis.</td><td>Diarrhea<br/>Vomiting</td><td>Salmonella.<br/>Campylobacter (crampy abdominal Pain).<br/>Norovirus.<br/>Early toxic shock (staph and Strep exotoxins act as antitoxins).<br/>C – difficile (if recent A/B).</td></tr><tr><td>Zoonotic infectious.</td><td>Using unpasteurized milk.<br/>Under cooked meat.<br/>Exposure to animal diarrhea.<br/>Contact with birthing animals.<br/>Feeding lambs.<br/>Bird contact.</td><td>Salmonella.<br/>Campylobacter<br/>Listeria.<br/>C – difficile.</td></tr><tr><td>Haemorrhagic rash / purpa.</td><td>&nbsp;</td><td>Meningococcal.<br/>Pneumonia.<br/>GAS.</td></tr></tbody></table>', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-9d6f9d27', 't-mm-09-015', 'html', '<h3><strong>Rule out Allergies to A/B:</strong></h3>
<ul><li>Careful history Nausea/ Vomiting =&gt; intolerance not allergy.</li><li>Mild rash with penicillin =&gt; 1 – 3% are allergic to cephalosporins/ Cross reaction.</li><li>Anaphylaxis with penicillin =&gt;<em><strong> Avoid</strong></em></li><li>Cephalosporin.</li><li>carbapenem.</li><li><em><strong>Discuss</strong></em>: infection specialist.</li><li><em><strong>Alterative:</strong></em> Erythromycin, clindamycin, vancomycin.</li><li><strong>Potential sites outside the Genital Track &amp; their Presentation:</strong></li></ul>', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c7877c8c', 't-mm-09-015', 'html', '<table><tbody><tr><td><strong>Site</strong></td><td><strong>Diseases</strong></td><td><strong>Clinical Features</strong></td></tr><tr><td>Head</td><td>Meningitis.<br/>Meninges encephalitis</td><td>Photophobia.<br/>Neck stiffness.<br/>Altered conscious status.<br/>Delirium.<br/>Focal neurological seizers.</td></tr><tr><td>ENT</td><td>Otitis media<br/>Sinusitis.<br/>Pharyngitis.<br/>Laryngitis</td><td>Earache.<br/>Muffled hearing.<br/>Purulent nasal discharge.<br/>Fascial pain.<br/>Hoarse voice.<br/>Headache.<br/>Lymphadenopathy.<br/>Sore throat.</td></tr><tr><td>Chest</td><td>Pneumonia</td><td>Cough with sputum.<br/>Chest pain.<br/>Hypoxia.</td></tr><tr><td>Hepatic Biliary</td><td>Cholecystitis.<br/>Cholangitis Pancreatitis.</td><td>Rt upper quadrant pain.<br/>Murphy’s sign positive<br/>Pain radiates to back.</td></tr><tr><td>Abdomen</td><td>Gastroenteritis<br/>Appendicitis<br/>Bowel perfection.</td><td>Diarrhea.<br/>Vomiting.<br/>MC Burney sign +.<br/>Atypical presentation.<br/>Acute abdomen.</td></tr><tr><td>Breast</td><td>Mastitis<br/>Abscess<br/>Necrotizing Fasciitis</td><td>Pain.<br/>Burning.<br/>Inflammation in breast.</td></tr><tr><td>Urinary tract</td><td>UTI pyelonephritis<br/>Herpes</td><td>Dysuria, loin pain.<br/>Hematoma.<br/>Urinary retention.</td></tr><tr><td>Reginal anesthesia related infection</td><td>Meningitis.<br/>Spinal abscess</td><td>Headache.<br/>Focal neurology.<br/>Photophobia.<br/>Back pain<br/>permanent spinal cord or cauda equina damage.</td></tr><tr><td>Wond infection</td><td>C – section<br/>Episiotomy wound.<br/>VTE.<br/>I/V cannula site.</td><td>Skin and soft tissue infections.</td></tr><tr><td>Necrotizing fasciitis</td><td>N. F</td><td>Agonizing pain requiring increasing analgesia.<br/>Initially no obvious signs.<br/>Later may have blisters and bruises.</td></tr></tbody></table>', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-dd037e59', 't-mm-09-015', 'html', '<h3>Table 37. Potential sites outside the Genital Track &amp; their Presentation:</h3>
<h3><strong>Management:</strong></h3>
<h3><strong>MDT:</strong></h3>
<ul><li>Senior obstetrician</li><li>Senior anesthetistwithin 1 hour</li><li>Senior Midwife</li><li><em><strong>Expert MDT: </strong></em></li><li>urgently if sepsis not responding to initial management.</li><li><em><strong>Critical care Team:</strong></em></li><li>Urgent referral in severe or rapidly deteriorating cases of sepsis.</li></ul>
<h3><strong>Indications for Transfer to </strong><strong>ICU</strong><strong>:</strong></h3>
<h3><strong>CVS:</strong></h3>
<ul><li>Hypotension &lt; 90 mmHg systolic.</li><li>Lactate &gt; 4 mmol/lit persistent despite fluids resuscitation.</li><li>Suggesting need for vasopressor/ inotropic support.</li></ul>
<h3><strong>Respiratory:</strong></h3>
<ul><li>Pulmonary edema.</li><li>Need for mechanical ventilation.</li><li>Need for airway protection.</li></ul>
<h3><strong>Renal:</strong></h3>
<ul><li>Renal replacement Therapy.</li></ul>
<h3><strong>Neurological:</strong></h3>
<ul><li>Conscious level.</li></ul>
<h3><strong>Miscellaneous:</strong></h3>
<ul><li>MOD</li><li>Uncorrected acidosis.</li><li>Hypothermia.</li></ul>
<h3><strong>Surviving sepsis campaign Hour – 1 </strong><strong>Bundle</strong><strong> of care:</strong></h3>
<ul><li>Measure lactate. (Re measure if &gt; 2mmol/ lit within 1 hour).</li><li>Obtain blood cultures.</li><li>Broad spectrum antibiotics.</li><li>I/V fluids 30ml/kg crystalloids if lactate &gt; 4.</li><li>Apply vasopressors if hypotension after fluid resuscitation to maintain B.P MAP &gt; 65mnHg.</li></ul>
<h3><strong>Antibiotics:</strong></h3>
<ul><li>I/V Antibiotics within 1 hour in women @ high risk of sepsis or septic shock.</li><li>Use of sepsis bundle improve compliance with urgent management.</li><li>Early fluid resuscitation of crystalloids with immediate bolus of 500ml in women with hypotension and lactate &gt; 4mmol, urine output be strictly monitored with urometer – 1 hourly.</li><li>Choice of A/B depends upon local epidemiology.</li><li>Where sensitivity not known = piperacillin/ tazobactam or Meropenem (for G – negative) plus clindamycin (for G – positive + Anaerobes) provide very broad cover.</li><li>Vancomycin is advisable in case of MRSA.</li><li>Switch to specific antibiotics in case availability of culture reports.</li><li>Add I/V Acyclovir 500mg TDS, as part of 2nd line A/B in case of maternal deterioration with 1st line cover.</li><li>Pyrexia in labor &gt; 380C or high =&gt; GBS prophylaxis.</li><li>Consider VTE propylene in sepsis.</li></ul>
<h3><strong>Necrotizing Fasciitis:</strong></h3>
<ul><li>Post birth wound can lead to serious abdominal or perineal N.F.</li><li>Infection causing necrosis of superficial and deep and sub cutaneous tissues.</li><li>1.8/1000 C/section can lead to N.F.</li><li>Rapid for by GAS.</li><li>Spread is hematogenous or direct.</li><li>Visible signs are in later stages.</li><li>Require increasing analgesic.</li><li>increasing and out of proportion pain due to edema and thrombosis of arterial supply to nerves leading to increasing demand of analgesia.</li></ul>
<p>Obvious signs are later – bruises, Blisters.</p>
<ul><li>Urgent involvement of plastic surgeon, intensivist, and infection specialist.</li></ul>
<h3><strong>Treatment:</strong></h3>
<ul><li>Piperacillin – tazobactam</li><li>OR          + clindamycin + Meropenem                       vanco in case of</li><li>MRSA.</li><li>Clindamycin =&gt; switch off exotoxin.</li><li>MRSA =&gt; vancomycin should be added.</li><li>Streptococcal Toxic Shock Syndrome &lt; 50% pts have classical sunburn rash.</li><li>Staph TSS =&gt; 100% sun burn rash.</li><li>Resistance to these A/B or allergies =&gt; consult infection specialist.</li></ul>
<p><em><strong>(P – T – O)</strong></em></p>
<h3>Table 38. Important points regarding Antibiotics:</h3>', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-34a79b9e', 't-mm-09-015', 'html', '<table><tbody><tr><td>&nbsp;</td><td><strong>Spectrum</strong></td><td><strong>Points</strong></td></tr><tr><td>Co – amoxiclav</td><td>No activity against MRSA or Pseudomonas Active against most streptococci, staphylococci (MSSA) anaerobes and many Gram negatives</td><td>Concern about an increase in the risk of necrotizing enterocolitis in babies exposed to co-amoxiclav in utero</td></tr><tr><td>Metronidazole</td><td>Only covers anaerobes</td><td>Unnecessary if using clindamycin and piperacillin-tazobactam as each covers anaerobes well<br/>Used with e.g. cefotaxime as intrapartum prophylaxis for suspected chorioamnionitis if non-severe penicillin allergy</td></tr><tr><td>Clindamycin</td><td>covers most GAS (&gt;89%) ; GBS (67%) so should no longer be used for GBS prophylaxis , Covers most staphylococci, including<br/>many MRSA. and anaerobes Switches off exotoxin production<br/>Not renally excreted or nephrotoxic</td><td>Associated with increased risk of Clostridium difficile superinfection</td></tr><tr><td>Piperacillin – tazobactam.</td><td>Spectrum same as co-amoxiclav, but also many Gram positive and Gram-negative organisms, including pseudomonas<br/>No activity against MRSA<br/>Renal sparing (in contrast to aminoglycosides)<br/>Poor activity against ESBL, producing coliforms</td><td>Avoid in beta-lactam allergy Very poor CSF penetration</td></tr><tr><td>Cephalosporins e.g. ceftriaxone.</td><td>No activity against ESBL producing coliforms, pseudomonas or MRSA<br/>Cover beta-haemolytic streptococci including GAS and GBS (but not enterococci)</td><td>Should not be used if severe beta-lactam allergy Increased risk of C. difficle</td></tr><tr><td>Carbapenems</td><td>Very broad empirical cover, most Gram-negatives (including most ESBL-producers, anaerobes) Covers most Gram positives except MRSA CPE are resistant.</td><td>Not for severe beta-lactam allergy With moderate beta-lactam allergy &lt;1% cross reaction<br/>Excellent penetration including CSF</td></tr><tr><td>Gentamicin</td><td>Mainly Gram negative cover (including most pseudomonas)<br/>No streptococcal, or anerobic cover</td><td>Inactivated in pus/anaerobic conditions Nephrotoxic and ototoxic, so usually limited where possible to a stat dose for sepsis. (For endocarditis a lower dose is given twice daily. and then serum levels must be monitored)</td></tr><tr><td>Vancomycin</td><td>Covers MRSA. Recommended option in severe penicillin allergy for GBS prophylaxis.<br/>No cover for Gram negatives.<br/>Not absorbed orally, so always given intravenously unless treating C.difficile infection.</td><td>Serum levels need to be monitored due to the potential for renal and ototoxicity.<br/>Too rapid infusion can cause "red man syndrome" due to histamine release.</td></tr></tbody></table>', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
