INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-3aecdfff', 't-mm-09-022', 'html', '<ul><li>11 – 13 + 6weeks.</li><li>G. Age by CRL – twins /triplets (larger baby’s CRL is used for determination of gestational age).</li><li>No of Fetuses.</li><li>No of placenta.</li><li>Nuchal translucency.</li></ul>
<h3><strong>Chori</strong><strong>onicity:</strong></h3>
