INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-09-028', 'chap-mm-09-01', '15. VACCINATION IN PREGNANCY', 'Detailed medical reference and study guide on 15. VACCINATION IN PREGNANCY.', 28, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-013aa2b5', 't-mm-09-028', 'html', '<ul><li><strong>Types of immunity.</strong></li><li><em><strong>1. </strong></em><em><strong>Innate:</strong></em></li><li>Weak, Rapid response – in minutes.</li><li>Less specialized.</li><li>1st line of defense.</li></ul>
<h3>Components:</h3>
<ul><li>Monocytes, macrophages, epithelial cells, neutrophils</li><li><em><strong>2. </strong></em><em><strong>Adaptive:</strong></em></li><li>Strong, Slow response.</li><li>Specialized.</li></ul>
<h3>Components:</h3>
<ul><li>Lymphocytes &amp; their products.</li><li>Cytokines, antibodies.</li><li><strong>Types of Vaccines:</strong></li><li><em><strong>1. </strong></em><em><strong>Killed:</strong></em></li><li>Inferior to live, vaccine    safe in</li><li>Large doses required.     Pregnancy</li><li>Booster required.</li><li><em><strong>2. </strong></em><em><strong>Live:</strong></em>- C/I in pregnancy</li><li>Superior.- Given in</li><li>Single dose.consultation</li><li>Low dose.with Infectious</li><li>Booster not required.  disease specialist.</li></ul>
<h3><em><strong>3. </strong></em><em><strong>Purified Macro Molecules:</strong></em></h3>
<ul><li><strong>Inactive toxins:</strong></li><li>DPT – given in pregnancy @ 28 – 32 weeks.</li><li><strong>Conjugate vaccines:</strong></li><li>Hemophiluscan be given in</li><li>Influenza.Pregnancy under</li><li>Neisseriaspecial</li><li>Meningitidisconditions</li><li>Streptococcus</li><li>pneumoniae</li><li><strong>Sub unit:</strong></li><li>Hep B.</li></ul>
<h3><strong>Vaccination C/I in pregnancy:</strong></h3>
<ul><li>BCG.</li><li>Measles.</li><li>Mumps.</li><li>Rubella – avoid conception for 28 days.</li><li>varicella – avoid pregnancy for 28 days.</li><li>HPV</li></ul>
<h3><strong>Vaccines specifically indicated:</strong></h3>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-b7316c96', 't-mm-09-028', 'heading', '1. DPT – 28 – 32weeks.', 2) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-603319f6', 't-mm-09-028', 'html', '<ul><li>2. Influenza and COVID-19</li><li>@ any stage to all women.</li><li>Esp October – January.</li><li>Don’t give live influenza.</li></ul>
<p>3. Inactive polio.</p>
<p>(P – T – O)</p>
<h3><strong>Vaccines given in special circumstances:</strong></h3>', 3) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-99d0e658', 't-mm-09-028', 'html', '<table><tbody><tr><td><strong>Vaccines</strong></td><td><strong>Indications</strong></td></tr><tr><td>Hep A</td><td>1.  Long term liver disease.<br/>Hemophilia.<br/>Poor sanitary condition.<br/>Living near to sewage.<br/>Living with primates.<br/>Drug abusers.</td></tr><tr><td>Hep B</td><td>1. Sex workers.<br/>2. Living with Hep B positive.<br/>3. Drug abusers.<br/>4. Multiple sex partners.<br/>5. Regular transfusions.<br/>6. Liver disease or CKD.<br/>7. Travelling to endemic areas.</td></tr><tr><td>Meningococcal</td><td>1. Asplenia.<br/>2. Immune suppression.<br/>3. Complement deficiency.<br/>4. High risk endemics travel.<br/>5. University students &lt; 25 years of age<br/>6. Contact with infected individuals.</td></tr><tr><td>Pneumococcal</td><td>1. Asplenia.<br/>2. SCD.<br/>3. Splenectomy.<br/>4. HIV.</td></tr><tr><td>Typhoid</td><td>1. Travel to endemics.</td></tr><tr><td>Rabies</td><td>- Post exposure prophylaxis recommended<br/>- Pre – exposure prophylaxis – where risk of exposure to rabies is substantial.</td></tr><tr><td>Yellow fever</td><td>- High case fatality.<br/>- Given when travel is un avoidable.</td></tr></tbody></table>', 4) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
