INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-042055e3', 't-mm-10-031', 'html', '<ul><li>Short cervix length &lt; 25mm or less @ 16 weeks – 24 weeks</li><li>+ History ofPPROMOrCervical TraumaProphylactic cervical cerclage + ensure a plan is made and documented for removal of suture+ History ofPPROMOrCervical TraumaProphylactic cervical cerclage + ensure a plan is made and documented for removal of suture+ History ofPPROMOrCervical TraumaProphylactic cervical cerclage + ensure a plan is made and documented for removal of suture+ History ofPPROMOrCervical TraumaProphylactic cervical cerclage + ensure a plan is made and documented for removal of suture<strong>Short cervical length on ultra sound, &lt;25mm, carried out @ 16 – 24 weeks andPre – term birth before 34weeksOr 2nd  miscarriage from 16 weeks onwardProphylactic Vaginal progesterone 200mg capsulesStart from 16 weeks till 34 weeks.Short cervical length on ultra sound, &lt;25mm, carried out @ 16 – 24 weeks andPre – term birth before 34weeksOr 2nd  miscarriage from 16 weeks onwardProphylactic Vaginal progesterone 200mg capsulesStart from 16 weeks till 34 weeks.</strong>Short cervical length on ultra sound, &lt;25mm, carried out @ 16 – 24 weeks andPre – term birth before 34weeksOr 2nd  miscarriage from 16 weeks onward<strong>Prophylactic </strong><strong>Vaginal progesterone</strong><strong> 200mg capsules</strong>Start from 16 weeks till 34 weeks.Short cervical length on ultra sound, &lt;25mm, carried out @ 16 – 24 weeks andPre – term birth before 34weeksOr 2nd  miscarriage from 16 weeks onward<strong>Prophylactic </strong><strong>Vaginal progesterone</strong><strong> 200mg capsules</strong>Start from 16 weeks till 34 weeks.+ History of</li></ul>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
