INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-c4e1bd99', 't-mm-10-033', 'html', '<ul><li>4. Previous c/s due to dystocia</li><li>5. Weight &gt; 4kg</li><li>6. &lt; 4cm @ admission</li><li>7. No epidural</li></ul>', 5) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-8779bfec', 't-mm-10-033', 'heading', '8. VBAC @ 41 weeks', 6) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-671f1ccf', 't-mm-10-033', 'html', '<ul><li>9. Previous pre – term ISCS</li><li>10. &lt; 2 years’ interval</li><li>11. Non white</li><li>12. Male infants</li><li>Advance maternal age</li><li>Short structure.</li></ul>
<h3><strong>S/S of Rupture:</strong></h3>
<ul><li>Confirmatory triad of rupture in 10%: laparotomy</li><li>Augmentation + IOL =&gt; with care</li><li>2 – 3-fold      risk of rupture (1 – 2%)</li><li>1.5-fold      risk of C/S</li></ul>', 7) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-1d1d2063', 't-mm-10-033', 'html', '<table><tbody><tr><td><strong>No of C/S</strong></td><td><strong>Previa</strong><br/><strong>%</strong></td><td><strong>Ac</strong><strong>c</strong><strong>reta</strong><br/><strong>%</strong></td><td><strong>With previa ac</strong><strong>c</strong><strong>reta %</strong></td><td><strong>Hysterectomy</strong><br/><strong>%</strong></td></tr><tr><td>1</td><td>1</td><td>0.24</td><td>3</td><td>0.6</td></tr><tr><td>2</td><td>1.7</td><td>0.31</td><td>11</td><td>0.4</td></tr><tr><td>3</td><td>2.81</td><td>0.57</td><td>40</td><td>0.9</td></tr><tr><td>4</td><td>2.81</td><td>2.1</td><td>61</td><td>2.4</td></tr><tr><td>5</td><td>2.81</td><td>2.3</td><td>67</td><td>3.4</td></tr><tr><td>6</td><td>2.81</td><td>6.7</td><td>&nbsp;</td><td>8.9</td></tr></tbody></table>', 8) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-41a38e87', 't-mm-10-033', 'html', '<h3><strong>Rupture:</strong></h3>
<ul><li>90% in labor peek incidence @ 4 – 5cm</li><li>18% in 2nd stage</li><li>8% identified post delivery</li><li>14 – 33% require hysterectomy</li><li>Abnormal CTG in 66 – 76% of rupture</li></ul>
<h3><strong>Scar Thickness:</strong></h3>
<ul><li>0.6 – 2mm – PPV for defect I/p</li><li>2 – 4mm – NPV for defect I/P</li></ul>
<h3><strong>EFW:</strong></h3>
<ul><li>4kg – success of VBAC &lt; 50%</li><li>Rupture = 3.6%</li></ul>', 9) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
INSERT INTO topics (id, chapter_id, title, description, "order", is_published, author, source) VALUES ('t-mm-10-034', 'chap-mm-10-01', '10. SHOULDER DYSTOCIA (SD)', 'Detailed medical reference and study guide on 10. SHOULDER DYSTOCIA (SD).', 34, true, 'Dr. Farzana Muneer', 'Maternal Mind FCPS/MRCOG Textbook') ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_published=true;
INSERT INTO content_blocks (id, topic_id, type, content, "order") VALUES ('cb-5f618fae', 't-mm-10-034', 'html', '<ul><li>-incidence 0.58 – 0.70%</li><li>48% in infants weighing &lt; 4kg</li></ul>
<p><strong>Prediction </strong>– 16% by conventional methods</p>
<h3><strong>Brachial Plexus Injury:</strong></h3>
<p><strong>BPI</strong> – is commonest cause of litigation due to SD and 3rd common cause related to obstetrics.</p>
<p>Leads to 10% permanent neurological damage.</p>
<h3><strong>Risk factors</strong></h3>
<h3><strong>Pre labour</strong></h3>
<ul><li>1. Previous shoulder dystocia</li><li>2. Macrosomia &gt; 4.5kg</li></ul>', 1) ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, type=EXCLUDED.type;
